(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,743385,e=>{"use strict";var i=e.i(843476),l=e.i(811337);function s(e){let s={li:"li",p:"p",strong:"strong",ul:"ul",...(0,l.useMDXComponents)(),...e.components},{AnketaCollapse:r,AnketaGroup:c,AnketaList:d,AnketaPoint:h,AnketaProse:j,Whisper:x}=s;return r||n("AnketaCollapse",!0),c||n("AnketaGroup",!0),d||n("AnketaList",!0),h||n("AnketaPoint",!0),j||n("AnketaProse",!0),x||n("Whisper",!0),(0,i.jsxs)(c,{children:[(0,i.jsx)(r,{title:"Общая информация",defaultOpen:!0,children:(0,i.jsxs)(d,{children:[(0,i.jsxs)(h,{title:"Имя персонажа [русс|англ]",children:[(0,i.jsx)(s.p,{children:(0,i.jsx)(s.strong,{children:"Астрид Нансен | Astrid Nansen"})}),(0,i.jsxs)(s.ul,{children:["\n",(0,i.jsx)(s.li,{children:"«Зимаподобная сестра» — звание, которое она носила в прошлом;"}),"\n",(0,i.jsx)(s.li,{children:"«Солнцеподобная сестра» — нынешнее звание, отражающее её статус среди лунов;"}),"\n",(0,i.jsx)(s.li,{children:"«Звезда Юга» — прозвище, полученное за способность освещать южные горы ярким светом, подобно маяку для грешников."}),"\n"]})]}),(0,i.jsx)(h,{title:"Возраст",children:(0,i.jsxs)(s.ul,{children:["\n",(0,i.jsx)(s.li,{children:"прожитый на земле: 30 лет."}),"\n",(0,i.jsx)(s.li,{children:"дата рождения — 07.12.1489г. | смерти — 30.12.1519г."}),"\n",(0,i.jsx)(s.li,{children:"прожитый в Загробном мире как грешная душа: 499 лет"}),"\n"]})}),(0,i.jsx)(h,{title:"Пол",children:(0,i.jsx)(s.p,{children:"Женский"})}),(0,i.jsxs)(h,{title:"Раса",children:[(0,i.jsx)(s.p,{children:"Красный дракон (чжулун)."}),(0,i.jsxs)(s.ul,{children:["\n",(0,i.jsx)(s.li,{children:"Гордыня Астрид послужила одной из причин, по которой её семья ввергла себя в пучину кровавой мести: не сумев совладать с собственным эго, она отказалась простить обидчика, получив денежное извинение, и обрекла собственных детей на борьбу; она не смогла стерпеть проявленного к её фигуре неуважения, когда она сама пришла в дом обидчика, объявляя о грехе, павшем на того, кто убил её ребенка. С агрессией встречала любые напасти, в том числе — нападки на детей, и выливала всю её на противников, желая в одну из стычек с противницей воткнуть кинжал ей же в горло. Её мудрость характеризуется скорее изобретательностью: не желая выходить за того, кого избрали ей родители, поддалась соблазнению будущего мужа и вынудила жениться на себе — и объявила о том родителям, избежав, таким образом, нежеланного замужества;"}),"\n",(0,i.jsx)(s.li,{children:"Как чжулун, Астрид принадлежит к семье алых драконов, одной из ветвей расы лун. Она была вознесена до этого статуса после смерти за прощение, которое она явила в последние мгновения своей жизни. Её связь с сородичами глубока и священна, а утрата большинства из них во время нападения на Центральный дворец стала для неё тяжёлым ударом, определившим её отношение к грешникам."}),"\n"]})]})]})}),(0,i.jsxs)(r,{title:"Психологический профиль",children:[(0,i.jsx)(r,{title:"Характер",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(s.p,{children:"С молоком впитывая характер матери, Астрид училась быть сильной и смелой, с каждой каплей перенимая те черты, какие способна пробудить в себе мать во имя своего дитя. Весь образ Нансен, сплетенный из способности любить и способности действовать решительно, был создан из образов собственных родственниц и великими фьордами. Все это вплело алые нити, опоясывающие её характер. Любовь, которую способно испытывать её сердце, широка: она проявляется в отношении близких, друзей, даже к природе и животным, окружающим её — всем даровано право быть любимыми и защищаемыми. Каждому, кто нуждается в любви и защите, и достоин этого, Астрид готова приоткрыть своё сердце, поделиться светом собственной души… Все радости и чувства, которые она испытывает, прольются благословленным теплом драконьей милости: ради них Нансен будет готова пожертвовать своей жизнью. Особая связь, наследуемая через поколения её родичей с природой, с её широтами, с её цветами, с любыми её проявлениями, переродилась в чувство глубокого уважения и, поддерживаемая жизнью за чертой образованного общества, стала превозноситься. Особенно здесь, в Энкраже, обострилось это чувство: едва увидев широты этих краев, исследованные и неизвестные, её охватывает отголосок воспоминаний, который навевает ей шепот фьордов — некогда величие и звуки природы заставляли биться сердце чаще, заставляли чувствовать себя лишь малой частицей могущества открывающегося пейзажа… Любовь, испытываемая ей не в отношении сородичей, противоречива: с одной стороны, грешники для неё, под давлением культуры лун, воспитавшей её, не могут считаться равными, они — лишь дети, которых нужно направлять… и долгое время Астрид готова была дарить им свою любовь и защиту; с другой стороны — они явились причиной боли и страдания, нанеся расе лун удар, от которого они вряд ли смогут оправиться."}),(0,i.jsx)(s.p,{children:"Они преступили ту черту, которая позволила бы Нансен из благородных чувств испытывать к ним сожаление, и ныне всякая её любовь к ним, питавшаяся ранее расовым воспитанием, зачахла. Боль разочарования, которую они ей принесли, вряд ли можно утешить: в её представлении чума, поразившая несколько колосьев, погубит весь урожай. Чаша, ранее полная сожаления и нежности, опустела, оставив внутри себя боль, раздирающую её, делая жизнь невыносимой пыткой."}),(0,i.jsx)(s.p,{children:"И все же, несмотря на разочарование, гнев её постепенно стих: не считая грешников достойными, она склонна отказывать им в новом вреде, предпочитая мольбам в святилище горделивое молчание. Любовь, которую она сохранила в своем сердце незапятнанной скорбью или разочарованием — любовь к животным, также ставшая наследием её недолгой жизни. Но самая же великая, хотя и печальная, её любовь — к сородичам: она предана им, превозносит связь между ними до священной. Как и всякий, кто способен на любовь, Астрид в глубине души полна нежности и некоторой наивности в желании проявлять те чувства, которые испытывает. Сердце её часто болезненно сжималось при виде страданий, и она старалась таковых избежать, не принося вреда своей волей."}),(0,i.jsx)(s.p,{children:"Но прежде всего — и любви, и преданности, и сожаления, — в ней выступает решительность, распаляющая гордость ярким, ослепительным светом. Пылкая, как и подобает алым драконам, Нансен питает порой непреодолимое желание действия, увлекаемая новой идеей — и стремится воплотить её… по крайней мере, таковой она была до бедствий, обрушившихся на её сородичей. Нежность и трепет, с которыми она могла относиться к окружающим, едва ли остались, заменившись сначала на известную чжулунам гневливость, а позже, с растягивающейся болью утраты — на затянувшуюся зиму, потушившую огонь, горевший в ней. Эти чувства порой пробиваются в ней, наполняя взор мягкостью и нежностью, но все реже и реже из-за той боли, которую она испытывает за семью лун. Не существовало фигуры решительнее и увереннее, чем она, и вряд ли будет: Астрид не шепчет во тьме прохладных залов, не просит нижайшего дозволения, — если огонь внутри неё вдруг загорится, то потушить его будут способны лишь вещи столь величественные, сколь и благородные — исходящие от самого искреннего сердца. Решительность идет об руку со вспыльчивостью, встающей на защиту дорогих ей: это пламя, разгораясь, сжигает свойственную ей мягкость, олицетворяя тот типаж, что ей пришлось примерять на себя всю жизнь — матери-защитницы."})]})}),(0,i.jsx)(r,{title:"Страхи",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Падение Империи",children:(0,i.jsx)(s.p,{children:"Склонная отказывать в доверии тем, кто проживает рядом с источником скверны, боится, что Империя падет и все знания, которые нужно оберегать и охранять, окажутся либо разворованы и проданы, либо извращены."})}),(0,i.jsx)(h,{title:"Потеря собратьев",children:(0,i.jsx)(s.p,{children:"Теперь каждый лун на счету и потерять одного из немногих, приблизив крах Империи — настоящий кошмар, у которого есть шанс воплотиться в реальность."})}),(0,i.jsx)(h,{title:"Не найти печать",children:(0,i.jsx)(s.p,{children:"Если Астрид не преуспеет в своем начинании, то новые луны не появятся в Энкраже, что повлечет не только печаль от кончины своего вида, но и конец грешного мира в её представлении."})}),(0,i.jsx)(h,{title:"Прошлое",children:(0,i.jsx)(s.p,{children:"Полтора века своей жизни она сбегала от собственных воспоминаний и три с половиной училась с ними жить — точнее, игнорировать, скрывать за эмоциями и мыслями, присущими здешнему миру. Если откроется этот сундук Пандоры, неизвестно, что выйдет наружу…"})}),(0,i.jsx)(h,{title:"Неудержимость",children:(0,i.jsx)(s.p,{children:"В своих уверениях Астрид идет до конца, поэтому боится, что её неспособность вовремя остановиться повлечет за собой множество жертв."})})]})}),(0,i.jsx)(r,{title:"Мечты, цели",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(s.p,{children:(0,i.jsx)(s.strong,{children:"Мечта"})}),(0,i.jsx)(s.p,{children:"Увидеть появление новых лун."}),(0,i.jsx)(s.p,{children:(0,i.jsx)(s.strong,{children:"Цели"})}),(0,i.jsx)(s.p,{children:"Найти причастных к нападению на Центральный Дворец; или, если тех уже нет в мире грешников, их последователей и явить на суд лун — и вернуть себе долгожданное спокойствие."}),(0,i.jsx)(s.p,{children:"Вернуть утерянную печать лун."}),(0,i.jsx)(s.p,{children:"Узнать, что случилось с Эдмундом."}),(0,i.jsx)(s.p,{children:"Помочь в отвращении грядущего кризиса."})]})}),(0,i.jsx)(r,{title:"Биография (при жизни)",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(s.p,{children:"Рождение Астрид произошло в северной части Норвегии, рядом с рекой Намсен, от которой, претерпев изменения в качестве согласного, её род получил своё имя — Нансен. Четвертая дочь при отсутствии сына и преклонном возрасте отца не вселяла уверенности в будущий день: все последующие дети даже если и были мальчиками, то рано умирали — кто от слабости, кто от нахлопывающих поветрий, кроме последнего. Крупный и светлый мальчуган, родившийся последним в паре немолодого супруга и уже взрослой женщины, стал надеждой: наконец-то господь смилостивился над их семьей. И хотя нельзя сказать, что семья Нансен была бессметно богата и обладала какими-то титулами в ставшем, по сути, колонией королевстве, но достатка им хватало: и еда, и слуги, и большой дом. Не было и речи о проблемах в качестве подарка уходящей дочери: каждой доставались часть скота, украшения и драгоценности."}),(0,i.jsx)(s.p,{children:"Сестры Астрид рано покидали отчий дом: природа не обделила их красотой, а приданное — ухажерами, самым достойным из которых доставались в жены достигшие брачного возраста сестры Нансен. Разница между ними была столь мала, что свадебные пиры закатывались три года подряд, в перерыве между которыми успело родиться два племянника Астрид. Светловолосая мать передала лишь последней дочери свои золотистые волосы, отец — серые глаза, от матери ей достались острый ум и свойственная ему горделивость; от отца — вспыльчивость и такая же молниеносная отходчивость; сестры приучили её к ведению быта и капризности; младший брат, несмотря на разницу в возрасте, привил любовь к невинным приключениям: сбегать к находящемуся рядом с ними Люнгенфьорду, лежащему в рукаве Намсен. Именно здесь, наблюдая простирающийся вдаль фьорд, можно было насладиться величием окружающей природы: ни речки, ни леса не могли унять этого восторга перед великими каменными титанами, сжимающими водяную гладь в своих объятиях, сколько ни ходи, они всегда были столь велики и огромны, что заставляли чувствовать себя еще меньше, чем ты есть."}),(0,i.jsx)(s.p,{children:"Здесь произошла помолвка Астрид с Асмандом Бирре — воителем, потерявшим первую жену при родах их первенца. Перенимая кольцо из рук своего нареченного по воле родителей, обдуваемая ветрами фьорда, она пустила слезу: он не был тираном и знался как добрый человек, но все же ей претила идея так скоро покинуть родителей, перейдя в дом взрослого мужчины. И в то же время её красота начала цвести: мягкое лицо обрамлялось светлыми волосами и светлыми глазами, при свете дня кажущимися голубыми и при сумраке ночи — темно-зелеными; у неё была очаровательная улыбка, подчеркивающая мягкий румянец на замерзающих часто щеках. Она нравилась многим, но общество вряд ли могло позволить выйти богатой девушке за юнца: у того не было ни приданного, ни проявленных качеств. Отдать дочь молодому — отдать в ламы неизвестности, хотели ли этого родители?"}),(0,i.jsx)(s.p,{children:"Астрид, все же, пошедшая в равную меру и в мать, и в отца, терзалась этим наследием — она знала, чего хочет, но, в то же время, не могла пойти против воли родителей. В заботе о животных, принадлежащих отцу, она находила спокойствие: монотонность движения, сопровождаемая лишь жеванием травы, вводила в транс. Связь человека Средневековья, его стремление быть частью природы, а не противостоять ей, была сильна в отдаленном от Европы регионе. Именно здесь люди продолжали гадать на помете птиц, держать дома кроликов рядом с пряслами, ходить после кошмаров к попам, оставлять зачерствевшей хлеб на сене… Астрид была подвержена традициям отца и матери в той же мере, в которой ей были подвержены её дед и бабка — и их предки. В очередной раз прогуливаясь к фьорду, вспоминая, какой болью отразилось последнее её там появление, Нансен встретила очертание лани в лесу и решила вернуться домой. Там же, сев за веретено, она наблюдала за обеспокоенным на вид кроликом, и финальным аккордом её сомнения был кровяной сгусток в разбитом яйце."}),(0,i.jsx)(s.p,{children:"Следующим днем она должна была отправиться с отцом и братом в город, чтобы купить жемчуга для свадебного убранства и рассказала о том своему другу детства, Свейну Йенсену, он же попросил вечером прийти в лес — попрощаться с ним. Свейн был втайне влюблен в неё и то было прощальным актом: вскоре Астрид перейдет в другой социальный слой и вряд ли сможет проводить с ним столько времени за долгими прогулками и беседами. В лесу он вручил ей венок из березы, росшей у окраин леса, знаменовав, тем самым, её статус как верной подруги, а она же в обмен подарила ему одно из своих колец. По обратной дороге, когда они со Свейном разошлись, Астрид подверглась нападению поповича Рига, который был страстно влюблен в Нансен. Он схватил её за волосы и повалил на землю, желая надругаться над честью — забившееся сердце в неожиданности не смогло исторгнуть из уст Астрид ни звука: она смотрела с ужасом на лицо человека, бывшего её добрым знакомым. И тут же она вспомнила всего на миг, какой становилась её мать, когда одна из дочерей или же брат попадали в передряги; какой она была в решении конфликтов между ними: грозной и строгой, решительной и быстрой. Астрид закричала, пытаясь оттолкнуть Рига, царапалась и набрала размякшей во время весны земли в руку, и бросила мужчине в лицо. Слегка опешив от комка грязи, попавшего в глаза, попович рукой смахнул её — Нансен резко подняла колено, ударив его, но этого оказалось недостаточно: его лицо приблизилось к её шее, касаясь губами нежной кожи, вжимая бедное тело в землю. Астрид пыталась кричать, еще некоторое время безрезультатно умоляла, впивалась руками в мужские локти. Лишь чудом уловив момент, когда Риг расслабился, её удар настиг своей цели, и он болезненно вздохнул, сгорбившись над ней, даруя несколько секунд. Астрид, резко возмужав, нашла силы, чтобы выползти из-под него и бежать — к семье, осыпая свой путь молитвами любым богам — лишь бы кто-нибудь откликнулся. Боги откликнулись: Риг не побежал за своей неудавшейся жертвой, оставив идею завладеть ей, но месть за эту неудачу была страшнее: не уехавшие Нансены узнали о том, что их дочь якобы подвержена разврату и рассказывал об этом, похваляясь перед всеми, сам Риг. Мужья сестер, отец и мать, её друзья — все заступились за неё, но издевка, брошенная при Свейне, привела к драке, в которой Свейн получил ранение и, из-за неопытности лекаря, погиб."}),(0,i.jsx)(s.p,{children:"Сестра Свейна, Сасса, обвинила во всем Астрид: если бы не она, то всей трагедии бы не случилось. Йенсен ставила в укор Нансен её красоту: не будь той, то и всей трагедии бы не приключилось ни с Ригом, ни со Свейном. Волнения, возникшие по этому поводу, вновь вызвали заступничество родственников, а Астрид отправилась в монастырь — просить убежища на период до свадьбы, чтобы лишний раз не волновать родителей. Она посетила Намсенфьорд, впервые посмотрев в своё отражение на водной глади, и она поняла, что, действительно, прекрасна: ей в пору быть героиней из древних легенд. И все же, долг пересиливал: Нансен попала в монастырь и за щедрую плату отца смогла обеспечить себе там место для ночлега. Прогуливаясь рядом с монастырем, Астрид встретила юношу, Дьярви Остлунда, представителя такой же богатой семьи как и Нансен, но из других краев. Она привлекала Отслунда своей красотой и своим нравом: нежность в ней сплеталась с резкостью суждений, которая так привлекала мужчин, потому как каждый знал: умная жена — залог хорошего хозяйства. Дьярви соблазнил Астрид, но и она сама, возжелав его, не стала сопротивляться, и сбежала из монастыря. Нельзя сказать, что то было лишь желанием любви, Астрид понимала, что нравится Дьярви и, при должном желании, сможет уговорить его жениться на ней. Остлунд поддался женским уговорам и подарил ей своё кольцо, обозначив желание взять её в жены."}),(0,i.jsx)(s.p,{children:"Обрадовавшаяся Астрид побежала к сестрам, чтобы те, введя её в дом, утихомирили грядущий гнев отца. Родители были недовольны: это причиняло ущерб им не только как людям, чья дочь расторгла помолвку, но и финансово: Йенсен мог обидеться и это сулило бы не только их дружеским отношениям. Так или иначе, Астрид вернула обручальное кольцо Бирре и на том же месте — её любимом месте — песках Люнгенфьорда, уже официально приняла кольцо Дьярви. Однако еще до свадьбы она поняла, что беременна и ей пришлось рассказать об этом родителям; те разделили опасения дочери и поругались с ней: для отца и матери было большим ударом узнать о бесчестье дочери перед священным обетом и вкупе с отменой помолвки с Йенсеном несколько месяцев назад она навлекла на себя родительский гнев. Отец пригрозился не пустить её домой, если брак с Остлундом распадется, а мать наградила её молчанием. Родительский гнев можно было унять только одним — извинениями от Дьярви, что показалось Астрид лишним, так как она уже была его женой."}),(0,i.jsx)(s.p,{children:"Она была своевольной, но все же пошла на уступки и уговорила супруга прийти к родителям и принести желанные извинения. Её отец, поругавшись на него, все же даровал своё прощение, а мать отпустила грех дочери, хотя и предупредила её, что судить не им, но господу, и вряд ли он простит ей этот грех без истинного раскаяния. Астрид уехала в имение мужа и готовилась к родам. Первенцем, будто в отместку родителям, она родила мальчика, сказав, что так господь благословил этот брак. Она была еще юна и прекрасна, но слишком остра на язык: многие родственники Дьярви жаловались на неё, особенно его сестра, собирающаяся выходить замуж, а потому приехавшая повидать родственников."}),(0,i.jsx)(s.p,{children:"В честь дня рождения первенца-сына Дьярви дарит жене двух собак и кобылу, обязуя её ухаживать за последней лично: лошадь была дорогим удовольствием, хоть и полезным, и поэтому, раз уж муж выполнил просьбу жены, та должна доказать, что прошения её были не беспочвенны. Астрид, уже забеременевшая во второй раз, даже свалилась с лошади во время переправы через лес, но осталась цела. Второй ребенок тоже оказался мальчиком, он получил имя в честь деда — Албиан. И тогда в семье начались проблемы: Астрид была хорошей хозяйкой, порой даже слишком строгой и совместный быт так или иначе склонял супругов к ссорам. Она часто говорила, что вернет ему кольцо, заберет приданное и вернется к родителям в случае, если он не последует её воле: но, как показывала жизнь, её советы, особенно в столь отчаянном способе передачи, были хорошими, и мужу приходилось соглашаться. Астрид любила гулять с детьми и возить их до Согнефьорда — Края Исполинов, одного из величайших фьордов, открывающих вид на могучие горы. Это путешествие нельзя было назвать безопасным: горы были дикими и люди, их населявшие, могли не отличаться дружелюбным нравам, но Нансен всегда отнекивалась, говоря, что она не ходит в горы и лишь показывает детям красоты природы. Однако опасность все же случилась в один из разов, когда к их компании — Астрид, Улле и Албиана, — присоединился незнакомый мужчина, попытавшийся отнять кольца женщины, и это происшествие стало причиной крупной ссоры. Однажды наученная горьким опытом, Нансен носила с собой кинжал и смогла отогнать самонадеянного старика, но дети рассказали об этом отцу — Дьярви наказал жену и поссорился с ней, запретив посещать фьорд и наказал детям рассказывать обо всем, что касается их матери. Это повлекло за собой недовольство Астрид: почему же она, верная жена, прекраснейшая из Нансен, родившая ему двух сыновей, не вольна ступать туда, куда хочет? Она как хозяйка отвечала за кухню и за то, кто сколько получит еды, и во время этой ссоры поклялась, что до тех пор, пока Остлунд не отменит своего запрета, не будет его кормить. Дьярви, также сгоряча поклялся, что не возьмет у неё еды, пока она не извинится перед ним и ушел из родного крова. Люди, жившие рядом с ними, всегда узнавали об их ссорах, каждый раз наблюдая за тем, как разворачиваются события: супруги любили друг друга и всегда мирились через пару дней. Но эта ссора продлилась неделю: гордый Дьярви сначала ничего не ел, а после поехал к брату, где ел мало, и в итоге исхудал. Жена брата Отслунда пришла к Астрид с увещеваниями, что ей нужно простить мужа, пустить его домой. Хотя она и отозвалась на это предложение, все же собственная гордость не позволяла ей так просто простить его и потому она сказала, что пусть Сиф возвращается домой и скажет, что она заболела. Раз уж Астрид заболела, то еду будет раздавать служанка. Так и случилось: Дьярви вернулся домой и пока Нансен изображала из себя больную, помирился с ней."}),(0,i.jsx)(s.p,{children:"Но семейные дрязги, из раза в раз ставя под вопрос счастливое будущее, всегда быстро разрешались и были наименьшим злом, которое придется познать их семье. За последующие годы Астрид родила еще четверых детей: одного мальчика, Йосефа, и трех дочерей: Туву, Эстер и Сигне. Дети переняли не только красоту и светлые волосы матери, но и характер, что стало, в некотором роде, их проклятием: самоуверенные, шумные и в некоторой степени несносные, дети были воплощением всего неудобного, что можно подумать о ребенке. Астрид, несмотря на их бесконечные истерики и шалости, любила детей всем своим сердцем и за строгостью — а ей нравилось быть именно строгой матерью — скрывала любовь, описать силу которой не хватило бы таланта ни одному великому поэту. Днем она ругала их и наставляла, а ночью, когда они спали, гладила по волосам, провожая в увлекательное сновидение. Она сидела ночами у их кроватей, когда они болели, и защищала мальчиков от гнева отца. Нансен обучила некоторых из них верховой езде, научила ласково обращаться к населяющим их дом животным, наказала не причинять больших страданий на охоте; она научила их видеть красоту в обыденных пейзажах и привила любовь к фьордам. Все, что когда-либо знала она сама, Астрид передала своим детям и всегда ставила их превыше себя: никакие поветрия не могли уложить её в постель прежде детей и никакие угрозы мужа не могли остановить женщину в защите собственных чад. Сыновья её, переходя все больше под опеку мужа из-за возраста, плохо ладили с ним: Астрид была пылкой, резкой и, когда требовалось, нежной; Дьярви был строгим, когда детям надо было дать спуску, и мягким, когда нужно было следить за ними."}),(0,i.jsx)(s.p,{children:"Одной из причиной многочисленных споров между супругами стали украшения Астрид, которые пропали из шкатулки: дети воровали их, в связи с чем Нансен приказала мужу повлиять на детей, но он не смог — невинные кражи продолжились. Любовь к своим украшениям Астрид также переняла от матери, а её дети, очевидно, от неё самой: собранные и подаренные однажды, эти драгоценности сопровождали её во многих поездках, напоминая о доме, семье и друзьях. Потерять их означало для Астрид пережить неприятное потрясение, а потому она болезненно приняла промах супруга. На утро Дьярви передал детей служанке и повез жену к Люнгенфьорду — там они провели некоторое время и заодно наведались к отцу Астрид. Как оказалось, старик доживал последние дни, поэтому Нансен осталась дома, приказав супругу привезти детей."}),(0,i.jsx)(s.p,{children:"И именно тогда, едва младшей из дочерей Сигрид исполнился год, случилась трагедия, изменившая судьбу этой семьи навсегда. Дети не успели навестить деда до его смерти, но остались до прощания, под конец которого умерла и их бабка. Брат Астрид, Альф, вступил в свои права и принял родственников у себя. Через пару дней раздался первый роковой гром: Албиан вернулся вечером с чистым лицом, но с одеждой в красных разводах, в которых мать признала кровь. Её младшего сына, Йосефа, с ним не оказалось, и Астрид потребовала объяснений, позвав мужа. Оказалось, дети-Остлунды играли с детьми Асманда Бирре, некогда просившего и почти получившего руку Астрид, и Сассы Йенсен, сестры погибшего друга Астрид, у Люнгенфьорда, кидаясь друг в друга камнями. Родители не доглядели, а дети были слишком глупы, чтобы осознать всю опасность подобного развлечения: один из сыновей Асманда попал большим и острым камнем в голову Йосефу, тот упал, ударился о камень на земле, и не встал. Дети пытались привести того в чувство, но безрезультатно. Сердце, забившееся подобно птице, требовало найти всему разумное объяснение, в котором нельзя было признать смерти собственного ребенка. Дьярви и Астрид отправились к фьорду, где и нашли уже остывшее тело их младшего сына."}),(0,i.jsx)(x,{children:(0,i.jsx)(s.p,{children:"Вечер, переходящий в ночь, опустошил бескрайние скалистые берега фьорда, погружая малую часть земли, поросшую травой перед водой, в тень. Свет луны, оставляющий серебристую дорожку на спокойной воде, жутким столпом падал на малую часть той земли, подсвечивая белоснежную кожу. Крик, раздавшийся рядом с этим местом, разлетелся по всему фьорду демоническим плачем — это был крик матери, прижимающей к своему голубому платью, слишком прохладному для ночи, бездыханное тело её ребенка: Дьярви не решался смотреть на жену, но бросив на неё взгляд, с ужасом понял, насколько были похожи Йосеф и Астрид. Сжимающая дитя в своих тонких руках, Нансен сама походила на призрака: красота покинула её лицо, смешавшись в гневе, отвращении и печали, и даже так — она ласково гладила по голове точную копию себя — но многим меньше… Её крик перешел в стенания, прежде чем прекратиться кровавой клятвой «Мне нужен Йёрн Бирре!"})}),(0,i.jsx)(s.p,{children:"Печаль Астрид слишком быстро переросла в гнев: страшные догадки, терзавшие её тело, пока оно надеялось на чудо, привели к тому, что она вспомнила о кровавых обычаях своего народа — о запрещенной, но так необходимой мере правосудия! Как Один велел при помощи рун почитать его и порядок, так и Астрид хотела при помощи слов воззвать к божественному правосудию. Она несла мертвого Йосефа на руках когда с рассветом вернулась в деревню, еще больше стала походить на призрака. Она вызвала к себе Сассу, но не дождавшись её прихода, игнорируя просьбы супруга, сама явилась в их дом: обвинять хозяйку у её же очага было страшным неуважением, но Асманд смог уговорить жену принять некогда возлюбленную её погибшего брата. Сасса, однако, заявила, что эта смерть давно ждала кровь Астрид, божественная воля направила руку её сына, Йёрна, когда он кинул камень в Йосефа — за погибшего за честь Астрид Свейна Йесенсена, брата Сассы и дяди Йёрна. Астрид, терзаемая грустью во время разговора, была уже готова согласиться на выплату виры, которую предлагал её муж, но услышав эту дерзость, не попрощалась с хозяевами и ушла, гордо подняв голову — с такими низкими людьми иметь дела было бы верхом стыда… и дома её ждало тело Йосефа, нужно было сходить к священнику и сестрам, выслушать совет мужа и брата."}),(0,i.jsx)(s.p,{children:"Смерть ребенка — страшное испытание, которое Астрид могла и не пережить: она перестала есть, перестала разговаривать, забыла обо всех, убиваясь собственной печалью. Лишь когда тело ребенка оказалось в земле возле деревянной церкви и Дьярви вместе с сыновьями, Улле и Албианом, совместно с их дядей, братом Астрид, Альфом, и мужьями сестер Астрид, Альвы, Альфхильды и Асы, Вермандом, Бергтором и Бьёрном, воздвигли надгробный камень, её душа покинула состояние печали, переродившись в чувство, испытанное ей, когда она держала в руках тело Йосефа — гнев. Как могла она, низменная и глупая Сасса, дочь Асманда пастуха, и внучка Верманда, которого принял в их поселении дед Астрид, просить у господа кровной справедливости в том, в чем Астрид виновата не была? Она не давала Свейну надежды, не принимала никаких его подарков кроме тех, которые было принято дарить друзьям, с достоинством проводила его в последний путь и поминала хорошим словом в своих воспоминаниях — и отплатой за это уважение с её стороны, жены богатого Дьярви, дочери воинственного Ганнара, внучки принявшего в своем доме деда нынешних Йесенсенов доброго Гутбренда, стала столь низменная месть? Сердце её пылало, слезы жгли глаза, кровь отлынула от рук, пытаясь охладить сердце: Астрид была готова сейчас же взять кинжал и нести возмездие за собственного ребенка: сын — за сына! Ярость, воспылавшая в ней, заставила гневно трястись от злобы, проглатывая любое добро, какое только могло быть в сердце: её сын!.. Дьярви сжал покрепче её в объятиях и не отпускал до тех пор, пока не почувствовал, как женские плечи расслабились, а гневливые вздохи обернулись тихими всхлипами — от чувств, распирающих душу, Нансен не могла сдерживаться. Она металась от деревянной стены к стене, кусая пальцы и смахивая лезущие в рот волосы, плакала и кричала, смеялась и задыхалась в рыданиях — её маленький, невинный сын, погиб, а его убийца жив! Альф, брат Астрид, позвал жену Алеифир следить за ней и пригласил своих родичей побыть в гостях еще — пока жена и мать Остлундов не придет в себя."}),(0,i.jsx)(s.p,{children:"Она повторяла лишь одно — «Мне нужен Йёрн!», ругаясь с мужем, и это услышали дети. Вечером того же дня её средний сын, Албиан, вернулся весь в крови и сказал матери, что отомстил — забил камнями младшего сына Бирре, Юнаса. Желавший порадовать мать, он не встретил улыбки на её лице — отстраненная, она вдруг «вернулась», но во взгляде её пробежала еще незнакомый ребенку родительский страх. Она резко встала, обняла Албиана и послала его к сестрам — а сама отправилась к мужу. Сказанное во гневе желание получить жизнь убийцы её сына обернулось смертью невинного ребенка, и Астрид ужаснулась тому, что сама же совершила, и она прекрасно знала, что этим дело не окончится. Не дойдя до Дьярви, она побежала к детям."}),(0,i.jsxs)(x,{children:[(0,i.jsx)(s.p,{children:"— Мама? — голубые глаза, уже испуганные, посмотрели на мать."}),(0,i.jsx)(s.p,{children:"Астрид ворвалась к ним так, будто случился пожар и сжала тонкие пальцы на только начавших формироваться мужских плечах так, будто требовало нечто важное, что-то, что могло приравняться только к страшному секрету."}),(0,i.jsx)(s.p,{children:"— Тебя кто-нибудь видел? — взгляд матери был тяжелым, практически безумным, на глаза ребенка навернулись слезы. — Албиан, я задала вопрос: тебя кто-нибудь видел?"}),(0,i.jsx)(s.p,{children:"Ребенок повертел головой, утирая слезы."}),(0,i.jsx)(s.p,{children:"— Мы никому не скажем, ни отцу, ни брату, ни сестрам, — она потормошила его, — ты меня понял?"}),(0,i.jsx)(s.p,{children:"Ребенок, слишком испугавшийся материнского гнева, уже начавший тихонько плакать, единожды кивнул"})]}),(0,i.jsx)(s.p,{children:"Страшная тайна, конечно, долго тайной не продержалась: Дьярви, заметив, что его вечно-веселый ребенок грустит, подозвал его и спросил, не по той ли это причине, что он скучает по Йосефу? Хотя Албиан кивнул, он сделал это слабо, как бы говоря, что не в одном этом проблема; умудренный спорами с Астрид, Дьярви напрягся: дети были точным отражением его жены, а уж её повадки он знал лучше самого себя. Албиан все рассказал отцу — и был вновь отправлен к сестрам и старшему брату, пока сам Остлунд-старший пошел к супруге. Он ничего не говорил, лишь посмотрел на неё с вызовом и положил руку ей на плечо, выражая ту степень понимания, которой вряд ли мог похвастаться муж, не имевший перед собой подобной беды. Им надо было уезжать и начались приготовления: Альф дал лошадей, Альва, Альфхильда и Аса дали еды, Верманд, Бергтор и Бьёрн вызвались их сопровождать до фьорда. Остлунды не приняли лишь помощь храбрых мужей: слишком рисково было просить их ехать с ними, навлекая, таким образом, кровавый глаз мести лишний раз на их родство. Оставалось продержаться день: следить, чтобы дети никуда не уходили, пока родители готовят их отъезд."}),(0,i.jsx)(s.p,{children:"Сердце Астрид болезненно сжалось от понимания, что это, возможно, последний день в родном ей месте: здесь она родилась, здесь прожила все детство, здесь жили её сестры и её брат, здесь был её дом, ныне дом Альфа, до того — дом Ганнара, а до него — дом Гутбренда… Здесь она училась шить, здесь училась готовить, здесь впервые укололась иглой, здесь же поняла, что Бирре ей не судьба. Мысли об этом навели её на воспоминание о том дне: неужто кровавый сгусток в желтке был верным знаком? Неужто эта кровь — кровь детей Астрид, неужто они должны расплачиваться за глупость Сассы? Астрид поглаживала собаку — наследницу нелепых ушей её далекой родственницы, бывшей верной подругой детства самой Астрид, и когда ворвался взволнованный Дьярви, она резко встала, вглядываясь в его лицо. Остлунд-старший говорил с ней спокойно, несмотря на видимое волнение, предлагая решить вопрос миром: они отдадут своих лошадей, среди которых была её любимица, отдадут собак, драгоценности и некоторых слуг, — этого, по мнению Дьярви, должно было хватить. Астрид посмотрела на него, заглядывая прямо в глаза, а затем отвернулась — нет. Не Астрид виновна в случившемся, не ей приползать на коленях к Асманду Бирре, которому десятилетия назад отказала в замужестве, и уж тем паче не к его наглой, нищей женушке! Они уедут вечером, осталось дождаться заката. Больше они сюда не вернутся, а если же Бирре-младшие посмеют явиться к ней домой, они дадут отпор, представив их разбойниками — и поминай как звали."}),(0,i.jsxs)(x,{children:[(0,i.jsx)(s.p,{children:"Ткань, когда-то имевшая голубой цвет, от старости потеряла свою яркость и представлялась при свете тепло-серой, зашуршала при быстрой ходьбе: Астрид сжала губы, быстрым шагом преодолевая расстояние от одного дома к другому, направляясь к местной знахарке."}),(0,i.jsx)(s.p,{children:"Прохлада улицы сменилась жаром дома и резким запахом трав, кажется, Астрид припоминала их названия, и согнувшись перед сухоцветами, подвешенными над входом, проникла в помещение. Она замерла — её муж, Дьярви, был ранен Асмандом Бирре, в отместку за то, что Остулнды нанесли им оскорбление и посмели убить младшего сына. Гнев и злость, питавшие её, вновь уступили поле сражения шоку: медленными шагами она размерила эту избушку: всего четырех шагов ей хватило, чтобы примкнуть к ложу, на котором медленно умирал её муж."}),(0,i.jsx)(s.p,{children:"На его лбу появилась испарина, лицо его стало бледным и бледными стали его губы: он в миг показался ей худым, каким-то излишне иссохшим, слишком неживым, чтобы представать перед ней. Он не издавал предсмертных стонов и не шевелился, лишь глаза слегка приоткрылись, когда её рука легла на его лоб. Он посмотрел на неё, слегка щурясь, будто её силуэт был слишком туманным, будто он сомневался, что это именно она, а не дочь или внучка знахарки или её сестра. Нансен опустилась на колени перед ним, коснувшись лбом его лба."}),(0,i.jsx)(s.p,{children:"— Асманду повезло, — с тонкой усмешкой, скорее от недостатка сил сказал он, прежде чем перевести взгляд на что-то, находившееся за спиной жены."}),(0,i.jsx)(s.p,{children:"Она молчала. Не знала, что сказать теперь, чувствуя, как слезы наворачиваются на глаза, пытаясь бороться с нарастающей истерикой. Глаза её блеснули — что-то, кажется, умерло в ней, и она накрыла его грудь своей рукой, от чего Дьярви болезненно зажмурился."}),(0,i.jsx)(s.p,{children:"— Ты понимаешь… — шепча произнес он, заглядывая ей в глаза; она хотела кивнуть, уверить его, что спасет детей и что она понимает все, что он хочет ей сказать; но внезапно он продолжил: — …что во всем виновата твоя чертова гордость?"})]}),(0,i.jsx)(s.p,{children:"Дьярви умер через несколько часов. Астрид поняла, призналась самой себе, что действительно любила мужа, хотя и женила его на себе лишь потому, что он показался ей отличным от других — его выбрала именно она, а не родители. Утерев слезы, она вернулась в родной дом, прося заступничества Альфа: он должен помочь ей добраться с детьми до «северной страны», Норланда, где она жила с Дьярви. Ночь уже опустилась на деревню, запрягли коней, собрали детей, уложили припасы — и двинулись. Альф предложил Астрид остановиться у фьорда — попрощаться, но она отказалась: это место умерло для неё, став могилой её сына, хотя мысль о том, что это было последним что он увидел — бескрайние каменные широты, уводящие воду далеко-далеко, чем-то согревала сердце… если можно было согреть сердце матери, потерявшей своего ребенка."}),(0,i.jsx)(s.p,{children:"Дети даже не смогли проститься с отцом — и в последующие несколько месяцев старались забыть о пережитом ужасе — потере двух мужчин их семьи… Астрид, не потерявшая, несмотря на выпавшие на её долю испытания, красоты, подумывала о том, что бы выйти замуж, но её останавливала бесправность старых детей в доме нового мужа: он не мог о них заботиться и не мог передать им своё наследство, а вместе с ним и имя — они были бы для него балластом, лишними голодными ртами. Прошел год — поветрия, пришедшие со стороны фьордов, распространились горячкой и страшными мучениями на слабых здоровьем и умом в родной земле Астрид. Она получила письмо от сестры, которая просила приехать, если не Остлундов-младших, то хотя бы саму Нансен — проститься… Альва, старшая сестра, имела даже спустя десятилетия влияние на свою сестру, и с тяжелым сердцем Астрид решила оставить детей их дяде по отцовской линии, Снорру Остлунду, а самой ехать в родные места."}),(0,i.jsx)(s.p,{children:"В процессе дороги в повозке кто-то чихнул: Астрид, сидевшая рядом с возничим, напряглась и просила сделать привал. Лошади, довольные этим решением, встали еще надолго, пока Астрид отчитывала своих несносных детей — Албиана и Туву, решивших поехать с матерью. Гнев её обратился на них самым страшным родительским укором: живое лицо сделалось мертвым в разочаровании. Разочаровании в самой себе, что не уследила, но вывалившимся на детей. Поворачивать означало бы потерять деньги, уже выплаченные, и заодно лишить себя возможности проститься с еще одним близким родственником: разве могла желать этого Астрид, бросившая похороны мужа на собственных сестер? И теперь, когда старшая сестра, проводившая в последний путь Дьярви, сама близка к этому пути, Астрид не явится? Что подумают о ней? Она, гордая дочь своего отца, один из драгоценных камней её семьи, умная и сильная Астрид из рода Нансен, не явится проститься с сестрой? Нет, быть того не может — они продолжили путь: дети будут заперты в доме средней сестры, пока Астрид уладит дела со старшей. А затем они уедут."}),(0,i.jsx)(s.p,{children:"Как выяснилось, поветрие в этих краях стало страшным испытанием: люди, не находя помощи, которую могли оказать врачи востока, и не находя даже той скудной врачебной подати, имевшейся в Норланде, умирали в собственных домах порой даже целыми семьями. Как некогда их предки умирали от незначительных ран из-за неясной, темной силы природы, так и нынешние жители преклонялись под гнетом божьей кары… И кара эта, что самовольно заметила Астрид, не обошла семейство Бирре: Асманд с двумя дочерьми скончались до приезда Нансен, к ним уже близилась бьющаяся в горячке Сасса. Вражда, развернувшаяся между ними, наконец отступила: каждый был занят своей судьбой, пока еще не думая взять у противницы как можно больше перед ликом смерти. Нансен привезла с собой травы и внутренности змей, наивно полагая, что чудесное лакомство средневековья из змеиного мяса и смеси многих трав излечит любую болезнь."}),(0,i.jsx)(s.p,{children:"Альва к приезду родственников начала поправляться, что списала на воссоединение семьи, хотя и не увидела племянников — все равно боясь расправы, Астрид отдала их сестре, семью которой болезнь не успела затронуть. Все темные мысли стали рассеиваться: за минувший год болезнь забрала жизни, однако земли стали оправляться от поветрия и многие стали чудом выздоравливать… по крайней мере те, кто по счастливой случайности оказывался «хорошим человеком»: попович Риг, пытавшийся изнасиловать Астрид, умер в день её приезда, но не столько от болезни, сколько от пьянства, выродившимся у него в жуткий, но непонятный недуг. Сестра выздоровела через неделю пребывания Астрид подле неё и собрала семью на пир: сама Альва, Астрид, Альфхильда, Аса, их мужья, Верманд, Бергтор и Бьёрн, их дети — Свейн, Сигурд, Синдр, Одд, Ильна, Арнейрд, Катрине, Ингрид, Леа и Албиан с Тувой собрались в одном зале. Счастливое воссоединение семьи будто залечило старые раны: не осталось ни страха, ни волнения — лишь достойнейшие истории из жизни и воспоминания, даже несмотря на то, что Верманд, Бергтор и Бьёрн были многим старше, они нашли общий язык со своей своячницей."}),(0,i.jsx)(s.p,{children:"Астрид с детьми согласилась остаться на неделю, навестить могилы сына и мужа, навестить Люнгенфьорд, с которым так и не простилась. Сасса прознала о том, что приехала Астрид с детьми и искала с ней встречи, но не заявляла об этом, а расспрашивала о ней, высматривала её фигуру — потеряв дочерей, она берегла сына, родившегося год назад, от посягательств горделивой Нансен. Несчастья, окончательно отравившие её разум сомнениями и болью, заставили видеть в кровной мести единственный способ унять обиду: почему её дети заболели и умерли, а дети Астрид живы и здоровы?"}),(0,i.jsx)(s.p,{children:"Нансен взяла дочь с собой в зимний лес, показывала знакомые ей деревья, рассказывала о том, какие чудеса творятся в нем ночью: когда темнота поглощает его, то выходят эльфы и исполняют свои самые замечательные танцы. «Именно потому нельзя ходить в лес ночью одному, — объясняла Астрид, — тех, кто бродит поодиночке, эльфы приглашают к своему танцу и делают эльфом, после чего человек уже не человек и, потому, не может жить среди людей». Прогулка по лесу действительно оказалась опасной, не из-за голодавших людей или похотливых мужчин, а из-за ненависти, рвущейся из сердца Сассы: она проследила за идущими вглубь леса Нансен и Остлунд-младшей и вернулась домой, прихватив охотничий нож, и побежала обратно к лесу. Она нашла прогуливающуюся дочь Астрид спустя некоторое время блуждания по замёрзшей земле. Сасса двинулась на маленькую Туву с ножом, шипя сквозь зубы проклятия, но дорогу ей преградила вышедшая из-за дерева Астрид, доставая украшенный резьбой нож. Уверенность Нансен противопоставлялась едкой ярости Сассы — женщины сцепились, хватая друг друга за волосы, пытаясь применить ножи, которыми до того лишь очищали овощи и разделывали животных, не используя их как оружие. Астрид вспомнила, какому нападению подверглась десятилетия назад рядом с этим лесом, а потому не позволила себе быть невинной жертвой: несмотря на боль, несмотря на холод, несмотря на страх, она вновь и вновь оттягивала волосы безумной, пыталась удержать руку с ножом, сама была готова воткнуть своё оружие той в глотку — эта тварь не могла и пальцем тронуть её дочь. Без ссадин не обошлось, ровно как и без ран: Сассе все же удалось совершить удар, впивающийся холодным лезвием в плечо Астрид, но и последняя, схватив руку противницы, сжала её и укусила со всей возможной в ней силой и яростью. Женщины отползли друг от друга подобно двум собакам, грызущимся за кость. Астрид выкрикивала проклятия в адрес Сассы, в спешке уводя дочь и забрав охотничий нож безумной противницы."}),(0,i.jsx)(s.p,{children:"Лезвие не вошло глубоко и хотя поранило нежную кожу, сильного вреда не нанесла — о том позаботилась знахарка, промывшая и перевязавшая рану, изготовив также мазь из целительных трав, заговорив их на уже бессмысленном, но незабытом памятью народа заклинании, требующего заступничества от Отца-Одина, властителя магии."}),(0,i.jsx)(s.p,{children:"Сассе тяжело обошелся этот воинственный поход — и без того больная, добравшись до дома, она совсем обессилила, пересказав все старшему сыну. Она просила, даже умоляла его закончить начатое и позаботиться, чтобы его младшему брату было нечего бояться… Сасса умерла несколько дней спустя от лихорадки, а её старший сын, Хевард, обвинил во всем Астрид, назвав её ведьмой. Безумцев, согласившихся поддержать эту мысль, не нашлось: все знали её с детства, видели её взлеты и падения. Однако сама мысль о колдовстве поселилась в их сердцах, заставляя вспомнить народную молву о черной смерти, бушевавшей в этих землях полтора столетия назад."}),(0,i.jsx)(s.p,{children:"Бьёрн, муж Альфхильды, взял Албиана на охоту и вернулся с окровавленным телом к вечеру — Хрольфр, как оказалось, видел, кто убил его брата и решил следовать клятве, данной матери. Он пустил стрелу в Албиана, но не смог убежать от Бьёрна и был забит им как скот не только за смерть племянника, но и за то, что убил его исподтишка, лишив смерть Албиана в этой кровавой войне отголоска древних традиций. Потерю второго ребенка она перенесла хуже, чем потерю первого: слезы брызнули из её глаз, размочив засохшую кровь на губах Албиана, Нансен обнимала его тело и гладила по волосам, что-то шептала, будто вот-вот он проснется — но ребенок был мертв. Даже то, что тело Хрольфра так и осталось в лесу, без могилы, предоставленное зверью, не могло успокоить вновь открывшиеся раны: погиб ребенок, самый добрый из всей её семьи, виновный лишь в том, что хотел единожды угодить строгой матери. Она винила себя в том, что из-за собственной гордыни позволила отринуть рассудок и повернуть назад; из-за собственной алчности она пожалела затраченных денег, и вот чем ей это обернулось. Еще один сын, еще один цвет жизни для неё погас, оставшись в воспоминаниях: больше она не услышит, как он говорит «мама», растягивая первый слог, как чешет нос, когда не знает, что сказать, но не может покинуть беседу — еще один человек умер, и все — по вине грязной, незатейливой и ничтожной дуры! Астрид взяла кинжал и ночью выбралась из дома и добралась до другого конца деревни, подошла к дому Йесенсенов — посмотрела на это жилище, облагороженное Сассой. Нансен стояла напротив входа, громко стучась в дверь, пробуждая ото сна здешний народ. Её противница, как объявила женщина возраста матери Астрид, умерла, старший сын похоронил её и пропал, вместе с ним исчез и его младший брат, Йёрн — для виду: старуха пыталась спасти юнца от гнева Астрид. Астрид злобно цокнула, услышав это имя; тот, кто обрек её семью на это страдание, был еще жив! Каков щенок! Его пропажу Астрид с надеждой списала на падение в овраг или чего похуже: она возжелала, чтобы он сломал ногу и пытался выбраться, и пытался до тех пор, пока изнеможение не взяло бы его тело, прежде чем душа покинула тело. Она хотела, чтобы он испытывал жажду, испытывал голод, испытывал тоску и понимание, что его никто не найдет; она хотела, чтобы животные, учуяв кровь и скорую смерть, наблюдали за ним, не давая уснуть — и чтобы они впились в его грязный язык и руки, едва жизнь покинет их, и вырвали, сожрали глаза и вылизали глазницы — такой должна быть участь Йёрна, сына Асманда, внука Эге! И она знала: внутри, скорее всего, остался ребенок — последний сын Сассы родился перед их непосредственным столкновением и убить его, как показалось Астрид, было бы лучшей карой за все случившееся: такую кончину — кончину голодных зверей — достоен этот проклятый род. Решимость ворваться в дом остановила лишь средняя сестра, пришедшая с мужем, чтобы увести её домой, чтобы не кормить и без того великое горе мыслями о том, что хотелось бы сделать, но сделать было нельзя."}),(0,i.jsx)(s.p,{children:"Гнетущее состояние Астрид было вскоре поглощено новой заботой: похороны сына завершились жалобой от Тувы на боль в горле. Вечером у дочери Нансен появилась головная боль, сонливость, а вместе с ними и жар. Любая месть, планируемая женщиной, утихла перед новой напастью: ведь не могут же боги быть так жестоки к судьбе её невинной дочери… С каждым днем ей не становилось лучше, а Астрид была с ней и днем, и ночью: кормила, умывала, гладила по голове и рассказывала истории, знакомые ей с детства. Она делала все, чтобы скрасить дочери её ухудшающееся состояние, знахарка со своими травами не помогала и Астрид в сердцах выгнала старую женщину. Сама Астрид заболела: боль в горле переросла в температуру, с которой тело с израненной душой пролежало два дня — чудом болезнь отступала, пока Нансен молилась, чтобы весь недуг дочери перешел к ней. Болезнь, ставшая отступать от деревни, вернулась к тем, кто не заболевал — и тогда все вспомнили про колдовство."}),(0,i.jsx)(s.p,{children:"Безумие, которое охватило народ, можно было сравнить лишь с помешательством: во всей красе показала себя отдаленность их деревушки от апостольских дворцов. Брошенные без короля, жители Норвегии лишь гадали, кто правит ими, кому они платят заработанные с трудом деньги, сколько ни просили они явить им короля — ответ был один: величество занят. И неудивительно, что кровная месть, запрещенная еще Хаконом Старым, без надобной слежки продолжала процветать, хоть и в уменьшающихся постепенно масштабах. Даже священники и попы, цитируя Библию, применяли Святое Писание вместе с застывшим во времени фольклором: эльфы, танцующие в лесах, становились слугами дьявола; болезнь, вернувшаяся в края, именовалась ведьминым поветрием, уничтожить которое можно было лишь совершив подвиг Авраама. Староста решил, ссылаясь на слухи и доводы старух, что идеальным жертвоприношением станет Стиан Асмандссон из семьи Бирре — их младший сын."}),(0,i.jsx)(s.p,{children:"На глазах Астрид от болезни скончалась дочь: едва слышимый хрип во сне стал последним, что прозвучало в комнате. Астрид уже не могла больше плакать: она сидела, опустив голову на руки и наблюдала за телом мертвой дочери. Следующим утром было решено принести в жертву Асмандссона, отданного Ингрид, доброй, но слишком суеверной женщине: его вернули в дом Асманда и Сассы, и собирались его поджечь. Астрид, вне себя от горя, решилась пойти."}),(0,i.jsxs)(x,{children:[(0,i.jsx)(s.p,{children:"Её лицо осунулось, во взоре читалась наставшая внезапно ясность, когда она увидела дом, за которым наблюдала в ночи. Она наблюдала за тем, как вносят ребенка в дом, как собираются поджечь дерево, заставив ребенка мучиться от агонии из дыма и огня. Что-то в разбившемся сердце заболело так сильно, что Астрид прислонилась к стоящим рядом сестрам. Неожиданным ужасом на её лице отразилось произошедшее: неужели они и правда собираются сжечь заживо ребенка?"}),(0,i.jsx)(s.p,{children:"Астрид вышла вперед и зашла в дом, посмотрела на маленького мальчика: он был еще крохой, практически как её младшая дочь: большая голова, больше чем тело, увенчана большим взглядом непонимания, маленькие ручки и ножки, еще круглый детский животик… В нем она увидела и Асманда, и Сассу, и своего когда-то лучшего друга, Свейна. Этот ребенок не был злым, не был представлением зла и не нес смерти своим явлением на свет. Вся деревня облачилась в белые одежды, словно вспоминая своё древнее прошлое, будто шли не к детоубийству — а почитанию рунических камней. Она взяла ребенка на руки и вышла из дома. Её увещевания к жалости не помогали до тех пор, пока Астрид не напомнила, в какой кровавой войне замерли две их семьи: её — и его."}),(0,i.jsx)(s.p,{children:"— Ребенок не будет страдать, лишь прощение — ваше испытание!"}),(0,i.jsx)(s.p,{children:"Народ не сразу принял её слова, некоторое время царила ругань и крики, требования убить малыша, но Астрид прижимала его к себе — как собственного. Если таково испытание благородства, то она его выстоит, ведь кто, если не Астрид Ганнарсдоттер, сможет воспитать бывшего врага как верного друга? Или, как минимум, простить: кровавый долг будет уплачен ценой прощения, а не смертью младенцев. Она обнимала его, возможно, вкладывая всю ту любовь, что рвалась из неё к почившим сыновьям и дочери и она, возможно, уже не различала разницы между ними. Спасая ребенка, она унесла его прочь от чужих глаз и двинулась к фьорду."}),(0,i.jsx)(s.p,{children:"Она впервые пришла сюда с тех пор, как здесь умер её сын: теплый свет уже лился из-под облаков, освещая бесконечные каменные горизонты и подсвечивая водную гладь. Спокойствие прерывал лишь ветер, изредка поднимающийся с новой силой, свистя в ушах и разбрасывая светлые локоны по накрахмаленной сорочке. Она обернулась, когда услышала робкие шаги, преследующие её. Им оказался мальчик, подросток: уже складывались мужские плечи, округлость начала спадать с лица, и в нем она узнала того, с кого началась вся эта бессмысленная война. Йёрн."}),(0,i.jsx)(s.p,{children:"— Твой брат, — Астрид одарила улыбкой Стиана и перевела взгляд на Йёрна, протягивая ребенка."}),(0,i.jsx)(s.p,{children:"Йёрн моргнул несколько раз, удивленный этим поступком. Его сжатая челюсть была видна по фигурному, уставшему и обессиленному лицу: по всей видимости, без родителей он плохо питался. Он принял брата из рук врага и едва кивнул, выражая благодарность. Астрид отвернулась и посмотрела на любимый пейзаж: вся её боль, скопившаяся в сердце, разрешением этого конфликта начинала утихать. Слеза, потекшая по нежной щеке, не успела упасть наземь прежде самой Нансен: она сдавленно вскрикнула, когда почувствовала резкую боль. Йёрн воткнул в неё кинжал, положив неподалёку брата. Астрид от неожиданности оступилась и, натянув подол платья, под силой нового удара упала. Становившийся мужчиной, Йёрн стал сильнее: он сел на неё и взглянул в глаза, занося клинок над женской шеей:"}),(0,i.jsx)(s.p,{children:"— За мою маму, ведьма!"})]})]})}),(0,i.jsx)(r,{title:"Жизнь в Энкраже",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(s.p,{children:"Перерождение, сулившее Астрид, вознесло её до великой чести быть причисленной к тем, кто имел возможность услышать тех, кто давно покинул грешные души — семейству лун. Горделивая, прожившая остаток жизни в великом гневе и великой печали, она покрылась алой чешуей, и была принята в семью чжулун, род алых драконов. Здесь ей предстояло учиться заново. Перерождение очистило Астрид от боли и прошлых обид, осветило её разум благодатью незнания."}),(0,i.jsx)(s.p,{children:"Первые десятилетия она проводила во дворце, учась быть полезной своей семье: связь, объединявшая их, с каждым новым днем лишь усиливалась, ввергая всякий гнев в милость, а веселье — в искреннюю любовь, практически обожание. И все же всякий раз она смотрела с печалью на дали, простирающие перед дворцом: южные горы отчаянно о чем-то ей напоминали, что-то внутри неё болезненно сжималось от ощущения великого пространства перед собой, заключенного в горный пейзаж."}),(0,i.jsx)(s.p,{children:"Астрид, добрая и решительная по натуре, легко приняла устои своего общества и своего Министерства: ей нужно было вырасти над собой, чтобы быть причисленной к высоким чинам. Смелая и решительная, она училась подавлять собственный гнев, чтобы в будущем служить верным и беспристрастным советником, одним из многих, но все же — достойнейшим из достойнейших. Она изучала историю, религию и общества Энкража, все еще не покидая дворца; изучала медицину, изучала флору и фауну по ботаническим и зоологическим справочникам, постигала философию и историю Империи, пропитываясь при этом необъяснимым почитанием к фигуре Императора. Первой работой, которую ей доверили, было наблюдение за святилищем: мало кто из грешников был способен добраться до него, но фауна, как и время, все же брали над ним верх; сам принцип наблюдения дракона подчеркивал ту роль, которую они играли. Спустя десятилетие во дворце, Астрид совершила свой первый полет над южными горами, приземлившись рядом с пунктом, бывшим целью для самых преданных и отчаянных из грешников. Здесь же она и прослужила еще десять лет, прогуливаясь возле святилища и наблюдая за великой природой с великой высоты. Она нередко видела грешников у подножия и часто видела, как дойдя до него, они разворачивались; как, не справляясь с испытаниями, обусловленными природой, обращали свой путь вспять."}),(0,i.jsx)(s.p,{children:"Луны — семья и Астрид любит всех своих братьев и сестер, но как часто это бывает, среди семьи есть тот самый брат или та самая сестра, которые становятся ближе всех остальных. Им оказался представитель рода черных драконов, Эдмунд."}),(0,i.jsxs)(x,{children:[(0,i.jsx)(s.p,{children:"В окружающей ночной тишине Астрид, облокотившись о наружную стену святилища, склонила светлую голову к плечу в процессе медитации. Звуки природы, отчетливо слышимые здесь, вне стен Министерства, успокаивали своей естественной размеренностью, запах благовоний наполнил место чарующим ароматом, а уснувшая или только начавшая охотиться фауна не тревожила это место."}),(0,i.jsx)(s.p,{children:"— Отчего же мы здесь спим?"}),(0,i.jsx)(s.p,{children:"Глаза резко распахиваются, голова поднимается, тело принимает собранный вид, алая чешуя прорезается сквозь кожу, отгоняя приближающуюся руку. Большие глаза всматриваются в темноту и лишь через несколько секунд замечают рога и хвост сюаньлуна"})]}),(0,i.jsx)(s.p,{children:"Эдмунд оказался намного старше Астрид и предложил, помимо дружбы, своё наставничество в боевых искусствах, помимо того, что проходило под руководством его собратьев. Нансен же зналась ярой пособницей боевых искусств, полагаясь не только на магию, но и на собственное тело, и сделалась одной из любимейших учениц сюаньлунов в этой части среди алых драконов. От предложения она не отказалась, но и часто видеть черного дракона не могла. И все же каждая их встреча все больше показывала, что связь между лунами сильна даже невзирая на родовую принадлежность: между алым и черным драконом закладывалась та дружба, которую она так и не смогла познать в мире живых после смерти Свейна."}),(0,i.jsx)(s.p,{children:"Астрид, несмотря на высшую цель, к которой её готовили, не проявляла особого интереса к грешникам: она могла испытывать к ним симпатию, могла возжелать помочь им, но как показал опыт, её естество всегда стремилось обратно, во дворец, и поэтому даже за те годы, когда она была наивна и с ней можно было подружиться грешникам не из числа лун, чжулун не смогла обзавестись подобными связями. Она нашла некоторое удовольствие в продолжении изучения фауны: способности, полученные ей, представлялись ей особым указанием на её роль — и она много времени проводила, развивая эти дары."}),(0,i.jsx)(s.p,{children:"Со временем, когда её магические силы окрепли и предоставили возможность бороться, она стала отправляться в патрули с другими драконами, наблюдая за южными горами. Весьма сложный маршрут из горных цепей и редких вулканических озер делал южные горы интересным, но слегка печальным местом — и природа здесь была соответствующая. Она же и позволяла лунам не отвлекаться на внешний мир, воспитывая юные поколения, к которым относилась и Нансен. Порой она в составе нескольких лунов посещала дворцы других лунов, но лишь с той миссией, чтобы узнать об их местонахождении — Астрид еще не имела серьезного веса и вряд ли могла обсуждать с братьями и сестрами что-то кроме весьма общих тем. Тем не менее, она любила эти маленькие путешествия: чем ближе она была к лунам, тем ярче казалась ей жизнь."}),(0,i.jsxs)(x,{children:[(0,i.jsx)(s.p,{children:"— А волосы ты заколоть не пробовала? — осведомился Эдмунд, склонив вопросительно голову, улыбаясь, подначивая алого дракона."}),(0,i.jsx)(s.p,{children:"Вместо ответа Астрид резко повернулась и сделала выпад, который её учитель без особой тяжести парировал; последующий — отвел. Нансен нравилось сражаться, нравилось то, как с каждым месяцем движения её становятся увереннее и четче, а меч ощущается не отдельным предметом, а продолжением рук. Впрочем, до битвы с наставником ей было еще много учиться: едва ли минуло двадцать лет её существования, из которых год она имела редкие занятия у сюаньлунов. Она росла на глазах, но все еще была слабоватым, если не ничтожным, противником для воплощений войны. В завязавшимся бою, больше схожим на шутливый танец, Астрид задалась одной целью: услышать скрежет металла от столкновения с черной броней. Ловким движением, которое она не смогла предугадать, Эдмунд оказался за её спиной и в лишнее продолжение своей шутки дернул её за золотистые волосы, заставляя недовольно поддаться жесту, тянущему подборок вверх: она встретилась глазами с его носом и темными глазами, даже из перевернутого положения ясно показывающими искры насмехательства. Таков был метод обучения — провоцировать то, что так сильно просилось наружу: Астрид несколько секунд смотрела на друга, медленно опуская руку от меча, а затем резко подняла, потянувшись за каштановыми волосами. Но этот маневр не был благословлен удачей: мужская рука перехватила женскую и сжала, вынуждая выгнуть плечо."}),(0,i.jsx)(s.p,{children:"— И говорят еще, что алым драконам роль судей была предназначена за честность…"}),(0,i.jsx)(s.p,{children:"Астрид одернула руку, высвободив её из плена сюаньлуна:"}),(0,i.jsx)(s.p,{children:"— Еще раз!"})]}),(0,i.jsx)(s.p,{children:"Военное искусство, интересовавшее Астрид, давалось ей все же с трудом, сон после активных занятий понемногу начал взывать к прежней памяти. Нансен никогда не была воителем и все схватки, которые происходили в её жизни — хотя она этого и не помнила, — вряд ли можно было назвать достойными: её всегда то валили на землю, то втыкали куда-нибудь нож. И после смерти, тренируясь с наставниками из рода черных драконов, несмотря на прыть, ей чего-то не хватало и поединок не заканчивался похвалой. И после одного из тренировочных боев, задачей в котором было коснуться противника оружием, и Эдмунд дернул Астрид за волосы, ночью ей явилась восстановленная часть прошлого: какие-то отрывки из детства, попытка Рига изнасиловать её. Решившая переночевать во дворце сюаньлунов, она проснулась от этого кошмара и первым же делом прошла в покои Эдмунда и поделилась с сонным другом своими воспоминаниями и сомнениями. Он успокоил её, напомнив, что теперь это все не имеет значения и что в их обществе, где каждый друг другу как брат или сестра, подобного не случится: особая гармония царит между представителями лун — в отличие от других рас."}),(0,i.jsx)(s.p,{children:"Несмотря на успехи, проделанные Астрид, ей пришлось вернуться в родной дворец и южные горы — к своей работе над сакральным наблюдением за святилищем… и охране южных гор от непрошенных гостей. Годы проходили, Нансен обрастала все большей силой и вскоре смогла явить весьма неплохое владение огненной стихией — для дракона — и усилила силы собственной чешуи."}),(0,i.jsxs)(x,{children:[(0,i.jsx)(s.p,{children:"Астрид встала у края скалы, всматриваясь в глубины, которыми оказывались скалистые лабиринты подножия, сквозь небольшие промежутки между облаками, и заметила движение: что-то, отразив свет, мелькнуло у самого великого подножия. Сначала подумав, что это, возможно, случайность, Астрид вгляделась в тьму, а затем и вовсе, явив чешую, исторгла свет от огня сквозь промежутки между облаками. Она осветила фигуру, разглядеть которую казалось невозможным с такой высоты, и потому Астрид обернулась драконом, спикировала вниз — стена пламени, извернувшись из её рта, преградила грешнику путь, обугливая камни, прежде чем с оглушающим звуком перед ним приземлился дракон."}),(0,i.jsx)(s.p,{children:"Перед ней предстал Эдмунд, несший в руках нечто, обернутое тканью."}),(0,i.jsx)(s.p,{children:"— Все свои, — приподняв руки, произнес он, демонстрируя мирный жест, после чего подошел ближе и провел рукой над чешуей, но не коснулся её: руку обдало нестерпимым жаром, — я принес тебе кое-что, — сюаньлун продемонстрировал ей сверток."}),(0,i.jsx)(s.p,{children:"Астрид приняла форму человека, вопросительно склонила голову набок, прищурилась, вглядываясь в знакомые черты."}),(0,i.jsx)(s.p,{children:"— Почему пешком?"}),(0,i.jsx)(s.p,{children:"— Захотелось."}),(0,i.jsx)(s.p,{children:"— Почему? — она неодобрительно осмотрела его, подойдя ближе."}),(0,i.jsx)(s.p,{children:"Это напоминало не допрос, но фарс: чем сильнее она становилась, чем больше училась у чжулунов, тем стремительнее становился гневливый порок её души: всюду ей казался повод, чтобы злиться, быть подозрительной и даже безжалостной. Сюаньлун кивнул в сторону гор, покрытых облаками, как бы намекая, что следует двигаться и поднес к лицу Нансен подозрительный сверток — вновь намекая, что полететь не сможет: придется оставить ценный дар живущим внизу грешникам. Они двигались аккуратно и в то же время стремительно — Астрид освоилась в горах настолько, что знала, где стоит обойти и в какой из каменных лабиринтов нужно проследовать, чтобы избежать ненужных столкновений со здешними обитателями. Под смелым шагом черного дракона земля отдала дрожью, усиливающейся со временем, и Астрид потянула незатейливого брата назад, прижав рукой к скалистой стене, и дрожь земли унялась — существа, возжелавшие встретить неосторожных путников, почувствовав, что их территории не угрожают, отступились от своих планов. Астрид смерила Эдмунда очередным порицательным взглядом и ухватилась за его запястье, ведя за собой, подобно ребенку, своего брата. Они прошли над вулканическим озером, отражающим красную звезду, и только тогда чжулун отпустила руку сородича, позволяя ступать ныне свободно, святилище было неподалёку и опасности, каких можно было избежать за время длительного подъема, миновали их окончательно."}),(0,i.jsx)(s.p,{children:"— Что у тебя? — чешуя исчезла, оставляя лишь благородные рога и тянущийся за ней хвост."}),(0,i.jsx)(s.p,{children:"— Подарок."}),(0,i.jsx)(s.p,{children:"Ответом ему был вздох."}),(0,i.jsx)(s.p,{children:"— Я спрашивала не об этом."}),(0,i.jsx)(s.p,{children:"Сюаньлун положил сверток на землю и развернул его: внутри оказалось два кинжала, он взял один из них и кивнул ей, разрешая взять второй. Их тренировки еще не закончились"})]}),(0,i.jsx)(s.p,{children:"Луны учатся всю жизнь: сначала — в близком кругу своего рода, затем, при должном желании — у всей драконьей семьи; они живут, впитывая бесконечные знания своих библиотек, охраняя великие тайны и сокровища от излишне любопытных глаз. Астрид достигала все больших успехов в науках лун, в бою и в магии. Воспоминания, всплывающие в её памяти, постепенно восстанавливали картину её жизни: её мать, отца, сестер и брата; она вспомнила свою любимую лошадь, вспомнила собак, вспомнила о плохих знамениях. Но все же её жизнь, казавшаяся теперь далекой, была явлена ей не полностью: собственная душа оберегала её от грядущего разочарования, и сама Нансен не желала знать своего прошлого во всех его кровавых подробностях. Отстранённость от прошлой жизни, принимаемая ей, кажется, отводила возвращающиеся воспоминания, позволяя им утопать среди эмоций и воспоминаний, которые даровал ей Энкраж, однако для того, чтобы контролировать приход воспоминаний, она стала реже тренироваться с Эдмундом, связь с которым по необъяснимым причинам пробуждала их."}),(0,i.jsxs)(x,{children:[(0,i.jsx)(s.p,{children:"Спящий дракон олицетворял собой величие: тусклый свет, исходивший от чешуи, освещал пространство вокруг, разнося тепло на несколько миль вокруг себя. Вздымающееся при вдохе и выдохе тело спящего дракона распространяло, вместе со светом, ауру спокойствия, привлекая самых умиротворенных животных: рядом с Астрид разместилось несколько груммов и стайка молодых виленсов, отдыхающих в ореоле её блаженного тепла. Она олицетворяла собой секундную искру божественности, заставляя лишь представить, на что способны все луны, собравшись в одном месте — каким же будет свет истинного величия этих удивительных существ?"}),(0,i.jsx)(s.p,{children:"Однако даже такая малая идиллия легко разрушима: черная туча, поблескивая чешуей при свете, приближаясь, обратила на себя звериное внимание. Поднятые головы, следящие за этим движением, встрепенулись, переглядываясь: уже не дракон, но человек, испугал их — яркий свет, дарующий тепло и мир, столкнулся с аурой ужаса, исходящей от драконьего сородича. Груммы поспешили прочь, ближе к хвосту своей невольной защитницы, виленсы взлетели, поднимаясь, чтобы, когда опасность минует, вернуться к источнику блаженного тепла."}),(0,i.jsx)(s.p,{children:"— Надо полагать, раз ты, алый дракон, спишь, наступила зима?"})]}),(0,i.jsx)(s.p,{children:"Астрид, подступая к порогу своего столетия, временно покинула свой пост у святилища: оценив её воинские таланты и интерес к природе, Солнцеподобные брат и сестра разрешили ей исследовать фауну южных гор, в особенности — в зоне землетрясений, обозначавших деятельность вергардов, одних из самых, если не самых, опасных представителей южного животного мира. Ей не разрешали приближаться к ним — лишь издали наблюдать. В своих поисках Астрид изучила, насколько тогда могла, их поведение, и могла не появляться неделями в своих покоях, соблюдая все правила: наблюдать и собирать информацию. Она исследовала южные горы, исследовала предгорные леса, побывала в лесах под дворцом белых драконов, наблюдала за дивной жизнью амфибий в угодьях под дворцом лазуревых драконов… К 1719 году Астрид стала Зимаподобной сестрой — первой помощницей Солнцеподобной сестры. Она исследовала леса Энкража и горы, в особенности уделяя внимание последним, разыскивая вергардов; она повстречала оногадора и имела честь наблюдать за ним несколько мгновений, прежде чем тот улетел; она исследовала повадки деворантов, используя свою магию, смогла найти контакт со стаей синебудок, заплутав в лесах, наблюдала за аварагардами… Периодически она возвращалась к роли наблюдательницы за святилищем — с правом отвечать на прошения грешников."}),(0,i.jsxs)(x,{children:[(0,i.jsx)(s.p,{children:"Яркий свет, озарявший небо где-то высоко, подсвечивая место святилища, пробивался сквозь крохотные просветы между облаками световыми копьями, пронзающими испещренные острыми выступами скалы; на сей раз их встречи, спустя почти столетие, они не общались. Могущество её возросло: яркий свет, теплыми волнами расходящийся на метры вперед, притягивал в своей тихой песне умиротворяющей гармонии тех, с кем успела сдружиться и чье доверие успела завоевать Астрид: груммы, молодые виленсы, одинокие бовемы и, кажется, декрейсы — все они отдыхали в её окружении, наслаждаясь ощущением спокойствия и защищенности. Она только впадала в спячку: сон, продлившийся пока только несколько дней, был нарушен."}),(0,i.jsx)(s.p,{children:"Её свет, бьющий ярко, был почти таким же, каким могли сиять мудрейшие из лун — золотые драконы — но не ослеплял. Он согревал, умиротворял, притягивал и очищал. И все же свет, сколь силен он ни был, должен был бороться с аурой смерти и отчаяния, в некоторой степени безумия, исходившей от старого друга своей хозяйки. Дракону понадобилось приблизиться ближе, чем в прошлый раз, чтобы взволновать отдыхающих подле Астрид животных своей аурой, вынуждая покинуть объятья этого прелестного света. Эдмунд провел рукой над чешуей Астрид и его встретило только дружественное тепло, а не раскаленный пламень, как до того: уснув, она не желала причинить никому вреда или, видя свои сны, не испытывала тревог, сгущающихся над народом лун."}),(0,i.jsx)(s.p,{children:"— Так вот какая она, Звезда Юга, — коснувшись чешуи, произнес Эдмунд, призывая её проснуться до впадения в спячку."}),(0,i.jsx)(s.p,{children:"Она медленно открыла глаза, обратила взор к человеческому облику черного дракона, и недовольна вздохнула: чешуя засверкала, нагреваясь, по рогам пробежало пламя, изо рта повалила струйка дыма, прежде чем глаза вновь закрылись. Эдмунд покачал головой и коснулся её еще раз, чувствуя, каким обжигающим гневом было пропитано её просыпающееся тело. Он держал руку столько, сколько мог — недовольный и болезненный вздох его окончательно пробудил Астрид. Она вновь открыла глаза, пару раз моргнула, осознавая, кто перед ней, и приняла обличье человека."}),(0,i.jsx)(s.p,{children:"Своё прозвище — Звезды Юга, — она получила за то, каким ярким маяком могла становиться, освещая, подобно другим алым драконам, ночную мглу южных гор; и за свою удивительную службу: вряд ли существовало то, до чего решительная и умелая Нансен не могла добраться. Она стала достойным представителем Министерства и в её взгляде неизменно пылало осознание собственного статуса. Взгляд её измерял достоинство, которым была пропитана её фигура: ставшая воином и судьей, она сама являлась источником светлого в своей душе. Свечение, исходившее от неё, ушло вместе с чешуей, оставив в воспоминании лишь золотистые волосы и вечный румянец на щеках, погрузив двух драконов в привычную Энкражу тьму."}),(0,i.jsx)(s.p,{children:"— Эдмунд, — поздоровалась она, кивнув."}),(0,i.jsx)(s.p,{children:"— Я решил, что навещу тебя до того, как алые драконы разбудят тебя и отправят спать во дворец."}),(0,i.jsx)(s.p,{children:"Серьезный взгляд, блуждающий по нему, будто вновь оценивая, смягчился: глаза расслабились. Он протянул ей ладонь, показывая нанесенный ему ожог."}),(0,i.jsx)(s.p,{children:"— Прости."}),(0,i.jsx)(s.p,{children:"Эдмунд всмотрелся в её глаза: несмотря на строгость слов, душа её сожалела, он видел это по расстроившимся бровям, по взгляду, по самому её самочувствию. Они разделяли уважение друг к другу и искреннее удовольствие находясь в компании друг друга, обладали особой, «космической связью», которой овеяны луны, но в чем-то — даже сильнее; большее уважение она питала лишь к представителям Министерств лун и священной фигуре Императрицы. Астрид взяла его руку в свои тонкие ладони и провела по покрасневшим участкам кожи — ожоги затянулись, Эдмунд улыбнулся и положил руку на её ладони, дружелюбно сжав, выказывая ободрение."}),(0,i.jsx)(s.p,{children:"— Ты еще держишь при себе кинжал?"}),(0,i.jsx)(s.p,{children:"— А ты как думаешь? — она указала кивком вниз, на место, на котором до того лежала, вдавливая телом кинжал, оказавшийся теперь возле её ноги. Быстрым движением она достала его, склонив голову. — Хочешь преподать мне урок, учитель?"}),(0,i.jsx)(s.p,{children:"Вернувшаяся ей бодрость позволила произойти поединку, но даже так, без оружия у самого черного дракона, коснуться его было не так просто. Движения её стали стремительными и точными, вместо наступательной силы, показываемой ей ранее, она брала в расчет свою ловкость, стараясь обмануть противника, прежде чем нанести удар. Этот бой вряд ли можно было назвать этим словом, но именно в нем они проявляли ту степень радости от общества друг друга: ведь о чем же говорить алому дракону с черным? Дело первых — судить, вторых — сражаться; и оба они были хороши в своем деле, но недостаточно хороши — в делах друг друга. И все же, Астрид приятно удивляла своего учителя — до тех пор, пока он вновь, будто припоминая былые времена, не дернул шутливо её за волосы, а затем, перехватив её кинжал и неуловимым движением опрокинув на землю, не прислонил острие к горлу. Поднявшись, он протянул ей руку, помогая встать и возвращая кинжал. Однако с Астрид что-то случилось: глаза её сверкнули от какой-то сильной боли, что-то заставило её на секунду опешить, заставив Эдмунда внимательно посмотреть на неё в вопросе: что он сделал? Алый дракон внезапно накинулась на опешившего собрата, опрокидывая его и заведя кинжал — мужчина только приподнял руки, успокаивая её и говоря, что врага тут нет. Воспоминания, распаляющие боль сердца — о родителях, о муже, о погибших детях, о собственной смерти, — невольно повторив сцену, имевшую место при жизни, драконы воскресили воспоминания, пролившиеся скорбью на пылающую душу Нансен. Кинжал с ужасным звуком столкнулся с камнем — Астрид вытянула руку вперед и из глаз её полились слезы. Обессилив от нахлынувших её чувств, она не могла встать, и прижималась к чешуйчатой броне Эдмунда. Сюаньлун не шевелился, так и замер: с приподнятыми в локтях руками, замеревшими над золотыми волосами, не зная, что сказать и делать: провоцировать противника, обманывать его, манипулировать — этому был обучен вершитель войны, а когда же дела касались дел более глубоких, силу которых он и как лун, и как друг понимал, но, вместе с тем, понять не мог, — его брала оторопь."}),(0,i.jsx)(s.p,{children:"Зимаподобная сестра Астрид, Звезда Юга, отказывающая дошедшим до святилища грешникам в просьбах и мольбах, сопровождая своим ярким светом их путь обратно, неожиданно погасла, сделавшись лишь простой женщиной — такой, какой она была при жизни"})]}),(0,i.jsxs)(x,{children:[(0,i.jsx)(s.p,{children:"Их путь лежал в лабиринты южных гор — место, по легендам, основанное деятельностью существ, которых должен бояться каждый, ступая на территорию южных гор, — вергард. Сила, используемая алыми драконами для наблюдения за ними, сейчас находилась во владении и пользовании Зимаподобной сестрой, вызвавшейся исследовать причины землетрясений. Ни уговоры, ни подарки, ни магия не могла помочь ей совладать с могущественными зверьми, однако это нечто все же сыграло роль в успехе подобного предприятия."}),(0,i.jsx)(s.p,{children:"Черные драконы, чей отряд возглавил Эдмунд, были приглашены как помощь отряду Астрид, который уже давно не поднимался на поверхность. Боясь, что энергия повлияла на это или, в худшем случае, сами вергарды, было решено узнать о произошедшем. Звезду Юга нашли в месте, которое она прозвала неясным скандинавским словом, и жестом приказала молчать. Как оказалось, она возглавила отряд, собираясь наблюдать за личинками, и пыталась установить связь с этими жуткими существами, скрываясь, но оставляя им «подарки» — под влиянием действия артефакта те не нападали, но и близко не подпускали."}),(0,i.jsx)(s.p,{children:"Её доспех был изрядно испачкан, частично даже отсутствовал — в угоду меньшему звуку, который, прибавляясь к движению, и без того кричал знающим об их присутствии зверям. Испачканное в пыли и грязи лицо, выбившиеся их хвоста волосы, уставший вид: Зимаподобная сестра не жалела сил, раскрывая тайны загадочной деятельности этих могучих существ. Она пришла к какому-то выводу, но не могла его озвучить. Эдмунд положил руку на её плечо."}),(0,i.jsx)(s.p,{children:"— Нам нужно уходить, ты выполнила свою работу."}),(0,i.jsx)(s.p,{children:"Слабого света хватило, чтобы рассмотреть её сосредоточенный и гордый взгляд, переместившийся на его руку."}),(0,i.jsx)(s.p,{children:"— Нет."}),(0,i.jsx)(s.p,{children:"Она отказалась — серебряное солнце, запечатленное на груди её доспеха, обозначавшее звание Зимаподобной сестры, было исцарапано и представляло удручающую картину сохранности всего нагрудника, из-под которого проглядывал поддоспешник."}),(0,i.jsx)(s.p,{children:"— Ты нужна наверху, — сказал он, приподнимая брови в знак едва уловимого во тьме вызова её чести, — тебя зовут Солнцеподобные сестра и брат."}),(0,i.jsx)(s.p,{children:"— Эдмунд, — она всмотрелась в его лицо каким-то особым взглядом, появившимся у неё с тех пор, как она стала отвечать на прошения грешников у святилища, неизменно находя их пороки достойным аргументом отсутствия их права на мудрость чжулун. — Если ты лжешь мне…"}),(0,i.jsx)(s.p,{children:"Он не лгал — отчасти. Но беседе этой продлиться долго было не дано: лагерь чжулун занимал крохотное пространство, заставляя всех чуть ли не прижиматься друг к другу, не занимая территорию могучих существ: лишь сила артефакта останавливала нападения, но кто-то по неосторожности вышел за территорию его действия. Грохот, раздавшийся в бесконечной тьме, оглушал: к ним двигался один из вергардов."}),(0,i.jsx)(s.p,{children:"— Руку! — она подскочила к неаккуратному брату и рывком повалила его, притягивая к черте лагеря, секундой позже огромное тело вергарда промчалось рядом с ними — зверь атаковал."}),(0,i.jsx)(s.p,{children:"Она вышла вперед, не пересекая грани лагеря, и посмотрела на червя, чей покой они нарушили. Астрид знала, что им, скорее всего, бояться нечего, но все же жестом приказала двигаться к выходу, используя второй артефакт, данный сопровождающему сюаньлунов алому дракону, оставаясь одной. Ужасающая пасть предстала перед её лицом, когда шорох сзади взволновал её, но она не могла повернуться."}),(0,i.jsx)(s.p,{children:"— Я — чжулун Астрид, руковожу этими драконами, — веры в то, что её магия сработает, практически не было; как и не было уверенности, что, используя её, она не заставит вергарда поглотить её. — Прошу поверить мне: мы не хотели причинить вам вред."}),(0,i.jsx)(s.p,{children:"Увещевания её, кажется, не работали: пасть зверя все приближалась, пока сильная рука не оттащила её — как сделала Нансен это пару минут назад с другим драконом. Челюсть щёлкнула перед самым её носом, но все же отступила, меняя направление движения. Рука Эдмунда впилась в её, он кивнул на артефакт, намекая: у неё нет выбора."}),(0,i.jsx)(s.p,{children:"— Но кристаллы… — попыталась высказать свою идею Астрид, но была прервана грозным взглядом."}),(0,i.jsx)(s.p,{children:"— Мне неинтересно, Астрид, расскажешь это Министерству Слова, а теперь — выведи нас отсюда, — он схватил её за руку и подвел к артефакту, вручая его. — Переговоры окончены: ты возвращаешься наверх, к святилищу, землетрясения прекратились, твоя задача здесь окончена"})]}),(0,i.jsx)(s.p,{children:"Жизнь в Энкраже даже среди родных лун стала потихоньку утомлять Астрид. После рокового возвращения воспоминаний она и вовсе пожелала прекратить собственные страдания и намеревалась поддаться настроению, клонившему её так долго в сон. В 1720 году Астрид вновь покинула и передала свой пост у святилища, прекратив освещать часть горы, и скрылась во дворце чжулун, погрузившись в спячку. Но и это избавление было недолгим: в 1730 году грешники, ракшасы и оммедзи, напали на Центральный дворец, погрузив его в пыл сражения, а после обрушили, порабощая и пленяя не успевших скрыться и обессиливших лун."}),(0,i.jsx)(x,{children:(0,i.jsx)(s.p,{children:"Долгий сон, принесший спокойствие, прервался волнительным биением сердца: Астрид открыла глаза, в спешке надела доспехи и полетела в направлении зовущего её золотого дворца: боль наполняла её сердце, заставляя чешую пылать ярким пламенем, грозясь сжечь любого, кто причиняет боль её братьям и сестрам. Но когда она долетела, скорбь между лунами превысила боль: в блаженном месте, избранным дворцом, не было золотого сияния. Дворец пал — его обломки, уже разграбленные грешниками, были углями бывшего, уже увядающего величия. Смерть родственников смешалась с воспоминаниями о смерти мужа и детей, и Астрид, не найдя виновников перед собой, в скорби полетела в южный дворец. Сердце её истекало кровью, она истошно кричала, хватаясь лапами за воздух, пытаясь найти в нем опору — но не могла. Звезда Юга, долетев до южных гор, была поглощена отчаянием: не чувствуя сил, она падала, проламывая тонкие осколки гор, заваливая лабиринты — подняться лишившейся чувств от скорби Нансен помогли её братья и сестры, вернув во дворец"})}),(0,i.jsx)(s.p,{children:"Она была первой из тех, кто поддержал решение Императрицы и Министерств в наказании грешников. Астрид не сближалась с ними, но всегда старалась относиться к ним с участием — и никогда, хотя легенды до неё о том говорили, не сбрасывала никого с горы, отпуская жестким отказом, — и вот, чем окупилось её доверие. Она знала многих золотых драконов близко и поэтому потерю их, а также их дома, воспринимала, как и все луны, особо остро. В последний раз от святилища чжулунов исходил драконий свет: Астрид пролетела над горами и остановилась на выступе перед святилищем, гордым змеем представ перед сметенными на время облаками, озаряя не только горы и его подножие, но и донося свет дальше — и, взревев, поднялась в воздух, навеки погасив свет, который должен был сопровождать грешников, являть им знамение: за ними наблюдают. Луны отвернулись от них — Министерство Слова насылало смерчи, сжигающие все в своих огненных ветрах, провоцировало лавины, осыпи и обвалы: сами горы, повинуясь силе лун, стали орудием мести: камни, засыпавшие и испортившие всевозможные дороги, поднимались ураганами, которые отбрасывали куски породы на головы провинившихся. Сорок дней они поддерживали катаклизмы, вызывая грозы и молнии, превращая свои края в настоящие очаги катастроф, отбрасывающих жилища грешников близ них на века назад — к животной жестокости, которую те проявили в отношении благородных лун."}),(0,i.jsxs)(x,{children:[(0,i.jsx)(s.p,{children:"Они встретились, когда Дикая Охота все же смогла найти спасение от гнева Императрицы: катаклизмы еще не успели полностью исчезнуть: грозные ветра еще наполняли южные горы, сметая камни и пыль, ветви деревьев, но они утихали с каждой секундой — гнев лун покидал Энкраж, позволяя природе и грешникам восстановиться."}),(0,i.jsx)(s.p,{children:"Астрид наблюдала за всем с высоты южных гор в человечьем обличье: недостаточно низко, чтобы тревожить братьев и сестер, и недостаточно высоко, чтобы иметь возможность взирать на вызванные ими разрушения. Сердце, в котором до сих пор кипит боль и злость, болезненно сжимается: их роль заключается не только в нежном поглаживании по голове и сказочных причитаниях — порой, чтобы ребенок научился, одних слов мало. Наказание, нанесенное живущим внизу, окончательно определило отношение Империи к грешникам: все они прожжены скверной греха и им нет спасения."}),(0,i.jsx)(s.p,{children:"Она узнала летящего в её сторону дракона на фоне черного неба — Эдмунд. Грозная аура ощущалась даже издалека, ей не нужно было касаться его чешуи, чтобы испытать чувства, которые его обуревали: этот гнев и эта ярость, смешанные с печалью и тоской, желанием кричать и упасть без сил, были разделаем всеми лунами."}),(0,i.jsx)(s.p,{children:"Он подлетел к ней, увидев светлую фигуру, и смахнул могучим хвостом её фигуру от края горы, будто предостерегая и одергивая, как отец — неразумного ребенка. Эдмунд обратился в человека, вглядываясь в лицо чжулуна: брови её удивленно изогнулись и она напряглась. В следующую секунду она бросилась ему в объятья, прижимаясь всем телом, разделяя тонкую грань их совместного отчаяния. Одного его присутствия хватало, чтобы утихомирить бурю, бушующую в алом драконе, и Астрид почитала это высшим проявлением драконьей связи. Нансен приподняла голову, Эдмунд же её опустил; они улыбнулись друг другу, но слабой, призрачной улыбкой, затем кивнули — «все хорошо» — хотя, очевидно, врали друг другу"})]}),(0,i.jsx)(s.p,{children:"Луны «ушли»: скрылись во дворцах, посвящая себя собственному горю. Астрид же поклялась себе и Солнцеподобной сестре, что найдет и представит к суду тех, кто совершил коварное нападение. Но время шло: повинуясь приказу и снедаемая общей болью, Нансен возвращалась к тому состоянию, которое так истощало тело и разум, что дракона клонило в долгий сон. Чем больше времени она проводила взаперти, тем больше возвращалась к тому дню: а что, если бы она не спала? Что, если бы те, кто посвятил себя жизни среди… этих, обладал большей мудростью? Вопросы, которые она задавала себе, и задавала всему своему Министерству, окончательно сломили её дух. Век скорби, в котором Астрид уничтожала свой характер, отнимал каждым часом её желание остаться в здравом уме и памяти: пропадали многие её друзья, а замена не появлялась со времен Империи Черного Лотоса. Астрид была представительницей самого младшего — и последнего поколения лун."}),(0,i.jsxs)(x,{children:[(0,i.jsx)(s.p,{children:"Это была последняя их встреча: луны больше не покидали дворцы без большой надобности, лишившись своих сородичей и пребывая в умирающих дворцах, отсутствие желания путешествовать можно было объяснить. Империя вошла в новую, трагическую эпоху, и Астрид готовилась отойти ко многовековому сну, лишь бы избавить годы своего учения и затворничества от мыслей о роковом дне и роковой ошибке."}),(0,i.jsx)(s.p,{children:"Он вошел в её покои, сливаясь с тьмой, царящей в них, тарабанил пальцами по кольчуге, ожидая, когда Нансен обратит на него своё внимание. Необъяснимый свет, который он видел в ней, печально угас: в былые времена она озарила бы все помещение ярким светом, наполнив прохладные залы одухотворяющим теплом. Чешуя её все еще светилась, но едва ли этого воспоминания, которое она так бережно хранила, хватало на то, чтобы побороть апатию и ощущение трагедии, холодной хватки смерти у её ног."}),(0,i.jsx)(s.p,{children:"— Я слушаю, Эдмунд, — снимая латный наплечник произнесла чжулун усталым голосом, лишенным всякой надежды, будто не она двести лет ходила в них по залам, читая записи и книги, хранящиеся в библиотеке дворца, пытаясь ухватиться за крупицы ускользающего наследия."}),(0,i.jsx)(s.p,{children:"Черный дракон подошел к ней и помог развязать ремешки, удерживающие холодные пластины, дотронулся до чешуи на ключицах: она была холодной. Астрид обратила на него свой взгляд и, привстав, коснулась своим лбом его лба. Удовольствие от его присутствия уже не могло победить ту рану, которая расширялась и гноилась все эти годы, но этот ритуал — особенный для неё — она невольно выполнила."}),(0,i.jsx)(s.p,{children:"— Что это было? — спросил с тенью улыбки сюаньлун."}),(0,i.jsx)(s.p,{children:"— Не думай об этом, — Нансен скрыла лицо в ладонях, потирая глаза, запутавшись в собственных мыслях."}),(0,i.jsx)(s.p,{children:"— Я давно хотел тебе…"}),(0,i.jsx)(s.p,{children:"— Не стоит."}),(0,i.jsx)(s.p,{children:"Он положил руку ей на плечо, но Астрид сняла её, и продолжила избавляться от доспеха, оставаясь в белом нижнем платье, на котором было что-то вышито — узоры поблескивали, отражая слабый свет, исходивший от чжулуна — Звезда Юга готовилась к долгому сну."}),(0,i.jsx)(s.p,{children:"— И все же, Астрид. — он взял её за плечи, заставляя посмотреть себе в глаза."}),(0,i.jsx)(s.p,{children:"Она догадывалась лишь о двух причинах так говорить: взгляд его стал холоднее, чем был когда-то, и это означало, по её мнению, лишь одно: безумие подкрадывалось и в его ум; вторая причина казалась ей святотатством, и она всячески отрицала свои догадки. Ответ её не заставил себя долго ждать и был таким же, какой была сейчас её натура — холодным, умоляющим."}),(0,i.jsx)(s.p,{children:"— Ты не можешь."}),(0,i.jsx)(s.p,{children:"— Правда?"}),(0,i.jsx)(s.p,{children:"Одной рукой Эдмунд обвил её талию, притягивая себе, другой коснулся золотистых волос, положил кисть на затылок, большим пальцем коснулся щеки, смахивая слезу. Он притянул её к себе, и Астрид расслабилась, прикрывая глаза — губы Эдмунда накрыла аккуратная ладонь Нансен перед тем, как её мягкие губы собственной руки. Он в изумлении открыл глаза, смотря на то, как её лицо замерло в мучительном выражении, разделяемое с ним лишь её тонкой ручкой, и прижал сильнее."}),(0,i.jsx)(s.p,{children:"— Мы не можем…"}),(0,i.jsx)(s.p,{children:"Чешуйки, появившись на ней, покрылись огнем, начав нагреваться, предупреждая: её нужно отпустить. Он не отступил, но ничего не предпринимал, наблюдая за взглядом Астрид. Они смотрели друг на друга еще некоторое время, прежде чем Нансен улыбнулась — слабо и слишком наигранно, чтобы кого-то обмануть, вновь коснулась своим лбом чужого и отпрянула; вырвавшись из этих пут, она легла в постель и свет, исходивший от неё, окончательно угас. Она закрыла глаза, Эдмунду же оставалось только уйти, что он и сделал — прежде оставив рядом с ней своё кольцо. С открытой дверью луч света озарил комнату, осветив фигуру Астрид; черный дракон обернулся: её брови расслабились, волны длинных светлых волос разметались по подушке и она приобрела вид долгожданного умиротворения, принимая этот сон как благословенное решение проблем."}),(0,i.jsx)(s.p,{children:"— Это… не все, что я хотел тебе сказать, хотя и главное, — произнес он, надеясь вырвать её из пут одолевающего сна."}),(0,i.jsx)(s.p,{children:"Он остался без ответа и закрыл за собой дверь в её покои"})]}),(0,i.jsx)(s.p,{children:"Астрид получила желанное освобождение: сон поглотил её мысли и её разум, то развлекая чудесными снами, то их отсутствием. За те годы, что она спала, чжулуны не смели беспокоить Зимаподобную сестру и вскоре стали прощаться с этим миром. Единожды её сон, укрепившись в ней, истончился и был готов порвать тонкую завесу спокойствия: что-то кольнуло в её сердце и душе, явив странный сон об Эдмунде — с ним что-то произошло. Даже во сне её брови нахмурились и заточенное во сне тело шевельнулось — казалось, вот-вот она очнется, но буря неожиданно ушла. Эдмунд, что бы с ним ни случилось, исчез, оставив невинным воспоминанием последние его слова, на которые, по собственной гордыне и желании избавиться от несчастья, Астрид не отозвалась; и кольцо, преподнесенное как напоминание о нем."}),(0,i.jsx)(s.p,{children:"И вот зима, смешанная с пеплом, явила наглядно, что баланс сил нарушен: взрыв, прогремевший несколько часов назад, окончательно подтвердил догадки. Астрид ворочалась: спокойные сны, повествующие о лучшем, менялись на сны об Эдмунде, а теперь — о грядущей катастрофе. Сладкий сон перерос в кошмар, и Астрид открыла глаза. Сон исцелил её душу, хотя боль и тоска, до сих пор разделяемая лунами, не давала забыть о прошлом. Она заметила кольцо и невыразимое чувство — сладкая печаль — наполнила её: чжулун продела его через веревку и надела, спрятав украшение под тканью нижнего платья. Поднявшись, Нансен прошлась по потерявшему тепло дворцу: их славный род практически пресекся, оставив лишь её — и еще одного луна. Ныне Солнцеподобная сестра, Астрид, влекомая высшей идеей, пришедшей ей во сне, вышла на балкон — и вновь озарила ночь и облака ярким светом: мир позвал лун — и они явятся на этот зов."})]})})]}),(0,i.jsxs)(r,{title:"Дополнительно",children:[(0,i.jsx)(r,{title:"Факты о персонаже",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Связь с детьми",children:(0,i.jsx)(s.p,{children:"Связь Астрид с детьми завязана на игрушках: каждому из своих детей она дарила вырезанную Дьярви игрушку в виде оленёнка или лошадки."})}),(0,i.jsx)(h,{title:"Отношение к грешникам",children:(0,i.jsx)(s.p,{children:"Считает, что именно близость к грешникам, прежде всего цилиней и фэньхуан, подвела Империю к черте отравления. Не доверяет им и не проявляет особого радушия, однако способна — в теории — проникнуться к цилиням-женщинам той симпатией, какую оказывала в молодые годы — за схожесть своих интересов с их долгом."})}),(0,i.jsx)(h,{title:"Взгляд на цилиней и фэнхуан",children:(0,i.jsx)(s.p,{children:"В связи с недоверием к цилиням и фэнхуан свела их жизнь «внизу» и интерес к грешникам — предоставленным лунам — порочным, портящим их; им была дарована задача охранять природный мир Энкража и Третий Мир, но они, живя рядом с грешниками, не смогли отказать себе в удовольствии плениться своей властью и преступить порог, влившись в их общества и идя с ними рука об руку, и тем самым сами способствуют хаосу и развращению как сердец грешников, так и своих собственных: наверняка многие из них — по мнению самой Астрид — погрязли в грязных делах грешных душ."})}),(0,i.jsx)(h,{title:"Вера в Эдмунда",children:(0,i.jsx)(s.p,{children:"Верит, что Эдмунд не покинул Энкраж: она не знала о его жизни ничего, кроме того факта, что он старше неё на несколько веков; искренне верит в то, что, исчезни он или будь убит, то это разбудило бы её от спячки."})}),(0,i.jsx)(h,{title:"Внутренний конфликт",children:(0,i.jsx)(s.p,{children:"Находится в некотором подвешенном состоянии: с одной стороны, грешники для неё — истинная отрава, с другой — верит, что именно луны способны противостоять их темному влиянию и потому, хотя еще того не осознает, ищет грешника, к которому могла бы проникнуться если не уважением, то искренней симпатией и доверием."})}),(0,i.jsx)(h,{title:"Причина перерождения цилинем",children:(0,i.jsx)(s.p,{children:"Раньше считала, что ей суждено было переродиться цилинем, однако именно прощение Йесенсенов в лице их младшего отпрыска даровало ей право вознестись и примкнуть к тем, кто стоит выше обычных грешников."})}),(0,i.jsx)(h,{title:"Любовь к природе",children:(0,i.jsx)(s.p,{children:"Любовь ко всему живому — Астрид старается действовать из принципа наименьшего урона балансу и потому знается весьма сердобольной в отношении зверей. Может, между спасением стаи бовемов и грешника выберет именно первое, потому как не забыла и не простила тот удар, который вторые нанесли её расе."})})]})}),(0,i.jsx)(r,{title:"Внешность",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(s.p,{children:"Первое, что отмечают в Астрид — необычайной красоты волнистые светло-золотые волосы, отливающие теплым оттенком, так нехарактерные для культуры лун, имеющей восточные корни; и, несмотря на громкие звания, довольно доброе, местами милое лицо. Форма её лица мягкая, хотя и намекающая на наличие слабых скул, все же больше склонна к гладким линиям: аккуратный подбородок, чуть выступающий за линию челюсти, аккуратный нос, маленькие, но миловидные губы, серые глаза, при свете похожие на голубые, при сумраке — на зеленые. Лишь тонкие, изящные рога, скорее описываемые как рожки, вырастают из золотистых волос, напоминая смотрящему, что перед ним представительница драконьей семьи. Нансен не отличается высотой в росте, достигая около 162 см., сложена весьма аккуратно и, как и лицо, слегка округло: нежные, округлые плечи и аккуратные руки с тонкими пальцами не выдают в ней особой физической силы, какая обнаруживается на деле. Кожа светлая, холоднее чем тон волос, что позволяет им казаться некоторым ореолом вокруг неё; легкий розовый румянец, будто она только вышла с мороза, сохранился со времен её жизни в северной стране, подчеркивает глаза, в которых, чаще всего, из-за такого контраста, чудится некий, на деле ей чуждый, холодок."}),(0,i.jsx)(s.p,{children:"Драконья форма, которую принимает Астрид, мало чем отличается от остальных чжулунов: она воплощает себя в виде дракона с алой чешуей, с золотистой — напоминающей волосы — шерстью и двумя маленькими рогами, позади которых появляются еще два, поменьше, являющимися отличительной чертой Нансен среди представителей её расы."})]})}),(0,i.jsx)(r,{title:"Навыки и умения",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Физическая сила и ловкость",children:(0,i.jsx)(s.p,{children:"Обладает повышенной физической силой, которая все же уступает высокой ловкости. В форме дракона, соответственно, характеристики меняются."})}),(0,i.jsx)(h,{title:"Рукопашный бой",children:(0,i.jsx)(s.p,{children:"Не самый профессиональный боец, но постоять за себя с бойцом среднего уровня сумеет."})}),(0,i.jsx)(h,{title:"Фехтование на мечах",children:(0,i.jsx)(s.p,{children:"Обучалась у сюаньлун."})}),(0,i.jsx)(h,{title:"Навыки следопыта",children:(0,i.jsx)(s.p,{children:"Итог деятельности в Энкраже."})}),(0,i.jsx)(h,{title:"Верховая езда",children:(0,i.jsx)(s.p,{children:"Приобрела еще при жизни."})}),(0,i.jsx)(h,{title:"Знание флоры и фауны Энкража",children:(0,i.jsx)(s.p,{children:"Хорошо знакома с флорой Энкража и фауной — с первым по большей части в теории, со вторым — и на теории, и на практике. Годы изучения и взаимодействия с животными позволяют ей лучше понимать их повадки и прогнозировать поведение."})}),(0,i.jsx)(h,{title:"Языки",children:(0,i.jsx)(s.p,{children:"Древненорвежский, древнедатский, латынь, квелларий: старый квелларий — в меру способности его изучения, знакома с текстами и может цитировать их и воспроизводить языковые формулы; средний и современный квелларий — в совершенстве."})}),(0,i.jsx)(h,{title:"Распознавание лжи",children:(0,i.jsx)(s.p,{children:"Хорошо распознает ложь — как итог обучения у чжулунов, впрочем, не такой профессионал в этой области как байлуны."})}),(0,i.jsx)(h,{title:"Магия огня",children:(0,i.jsx)(s.p,{children:"Как чжулун, Астрид владеет огненной магией, способна исторгать пламя и нагревать свою чешую до нестерпимых температур."})}),(0,i.jsx)(h,{title:"Драконья форма",children:(0,i.jsx)(s.p,{children:"Способна принимать облик дракона, что значительно усиливает её физические характеристики, позволяет летать и использовать огненное дыхание."})})]})}),(0,i.jsx)(r,{title:"Слабости",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Воспоминания об Эдмунде",children:(0,i.jsx)(s.p,{children:"Особое чувство — напоминания об Эдмунде заставляют вернуться к чувству сожаления и печали, гнева и возвращают к порыву найти его, что если не помешает, то может серьезно отвлечь Астрид. Самое слабое её место — сумей кто-то изобразить это чарующее видение и даже она поддастся."})}),(0,i.jsx)(h,{title:"Драконий приоритет",children:(0,i.jsx)(s.p,{children:"Всегда бросится на помощь сородичу, даже если придется пострадать самой."})}),(0,i.jsx)(h,{title:"Недоверие к грешникам",children:(0,i.jsx)(s.p,{children:"Отравленные плоды — не доверяет грешникам, хотя инстинктивно тянется к ним, из-за чего часто возникают сложности во взаимодействии: Астрид считает себя в праве не указывать, но командовать над ними."})}),(0,i.jsx)(h,{title:"Увлечённость",children:(0,i.jsx)(s.p,{children:"Преследуя цель, которой задалась, может забыть учитывать мелкие детали."})}),(0,i.jsx)(h,{title:"Воспоминания о прошлой жизни",children:(0,i.jsx)(s.p,{children:"Астрид до сих пор учится жить с воспоминаниями о прошлом, но всякий раз опешивает, когда образ сыновей или мужа появляется перед её глазами. Пробуждение, которое даровало ей дар спокойствия, не способно обратить вспять саму память: пока что Астрид вспоминает о прошлом с печальной ностальгией, но если ей придется столкнуться с образами, которые имели место быть при событиях прошлого, она вряд ли сможет оставаться такой же спокойной. Грешники, которые способны возводить иллюзии, узнав об этом, смогут управлять Астрид: она будет склонна покинуть поле боя, если у неё есть выбор, если её разум переживет еще один акт бесконечного кошмара её жизни."})}),(0,i.jsx)(h,{title:"Любовь к животным",children:(0,i.jsx)(s.p,{children:"Любовь ко всему живому — Астрид старается действовать из принципа наименьшего урона балансу и потому знается весьма сердобольной в отношении зверей. Может, между спасением стаи бовемов и грешника выберет именно первое, потому как не забыла и не простила тот удар, который вторые нанесли её расе."})})]})}),(0,i.jsx)(r,{title:"Связанные персонажи",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Дьярви Остлунд",children:(0,i.jsx)(s.p,{children:"Муж, 40 лет. Связаны брачным кольцом."})}),(0,i.jsx)(h,{title:"Улле Остлунд",children:(0,i.jsx)(s.p,{children:"Сын, 20 лет. Связаны деревянной игрушкой в форме коня."})}),(0,i.jsx)(h,{title:"Албиан Остлунд",children:(0,i.jsx)(s.p,{children:"Сын, 18 лет. Связаны деревянной игрушкой в форме оленя."})}),(0,i.jsx)(h,{title:"Йосеф Остлунд",children:(0,i.jsx)(s.p,{children:"Сын, 15 лет. Связаны деревянной игрушкой в форме оленя."})}),(0,i.jsx)(h,{title:"Тува Остлунд",children:(0,i.jsx)(s.p,{children:"Дочь, 14 лет. Связаны деревянной игрушкой в форме оленя."})}),(0,i.jsx)(h,{title:"Эстер Остлунд",children:(0,i.jsx)(s.p,{children:"Дочь, 12 лет. Связаны деревянной игрушкой в форме коня."})}),(0,i.jsx)(h,{title:"Сигне Остлунд",children:(0,i.jsx)(s.p,{children:"Дочь, 2 года. Связаны деревянной игрушкой в форме коня."})})]})})]}),(0,i.jsx)(x,{children:(0,i.jsx)(s.p,{children:"Как же сложно любить и ненавидеть одновременно. Я сломлена этим внутренним конфликтом, подобно ветви под силой шторма, но каждый раз нахожу в себе силы продолжать — отчего же не можете вы?"})})]})}function n(e,i){throw Error("Expected "+(i?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}e.s(["default",0,function(e={}){let{wrapper:n}={...(0,l.useMDXComponents)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(s,{...e})}):s(e)}])}]);